window.DBD_DATA.perks.push(...[{"id":"eyes-of-belmont","rank":109,"tier":"B","roles":["Information","Team Support"],"summary":"Generator completions reveal the Killer, and every Killer Aura reveal you receive lasts 2 seconds longer.","metaStatus":"Good","skillLevel":"Low","soloQ":3,"swf":3,"unlockPriority":"Medium–High","glossaryKeys":["aura-reading","pressure"],"useCases":["Extend short Killer Aura effects into windows long enough to read direction and commitment.","Gain a built-in Killer read whenever a generator completes.","Amplify information builds that already rely on repeated Killer Aura reveals."],"counters":["Provides no benefit when the Killer cannot be read by Aura.","The generator-completion trigger is tied to team progress rather than your timing.","Needs other Aura perks to fully exploit the extension effect."],"pros":["Permanent +2 seconds to every Killer Aura reveal is unusually broad synergy.","Built-in generator-completion Aura read means the perk is not completely dependent on another slot.","Very easy to use."],"cons":["Pure information with no direct action-speed or chase bonus.","Much stronger in Aura-heavy builds than alone.","Undetectable and Aura denial can reduce value."],"analysis":["Eyes of Belmont opens the this band band because the +2-second extension is stronger than a simple one-off Aura perk. Many Killer reads are brief enough that an extra two seconds materially improves your ability to understand direction, target choice, and whether the Killer is actually rotating toward you.","The perk also supplies its own trigger whenever a generator completes. At Tier III that read is three seconds before the perk extends its own effect, giving a useful snapshot without requiring a second perk to function.","Its ceiling rises sharply when paired with Alert, Fogwise, Kindred, Scene Partner, or other repeated Killer Aura sources. Instead of creating new information, Eyes of Belmont improves the quality of every compatible read across the match.","It remains B because information alone does not guarantee survival or objective progress. Aura denial can also shut down the core value. Still, among synergy perks, it has an unusually broad and practical target pool."],"verdict":"An excellent Aura-build multiplier with a useful built-in trigger. Eyes of Belmont is not a standalone powerhouse, but two extra seconds can turn fleeting reads into genuinely actionable information.","publicationStatus":"published","tags":["Aura Reading","Synergy"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Trevor Belmont"},"synergyPerkIds":["alert","fogwise","kindred","scene-partner"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Alert","Fogwise","Kindred","Scene Partner"],"antiSynergies":[],"name":"Eyes of Belmont","alternateName":null,"source":"Trevor Belmont","status":"Live 10.2.0","currentEffect":"Whenever a Generator is completed, the Killer's Aura is revealed to you for 1/2/3 seconds. Eyes of Belmont adds 2 seconds to every instance of Killer Aura reveal you receive, and it benefits from its own extension.","activation":["A Generator must be completed for the perk's direct reveal."],"patchNote":"Latest live balance change (unknown): No material live balance change could be verified from available patch history.","plainEnglishSummary":"Generator completions reveal the Killer, and all Killer Aura reveals you receive last 2 seconds longer.","cooldown":null,"duration":["Direct Killer Aura reveal: 1/2/3 seconds, extended by 2 seconds by this perk.","All other Killer Aura reveals received by you are extended by 2 seconds."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["The +2-second extension applies to all instances of the Killer's Aura being revealed to you, and the perk's own Generator-completion reveal benefits from it."],"sourceCharacter":"Trevor Belmont","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"tenacity","rank":110,"tier":"B","roles":["Anti-Slug","Recovery","Mobility"],"summary":"While downed, recover while crawling, move up to 50% faster, reduce pain sounds, and block Aura reading.","metaStatus":"Good","skillLevel":"Low–Medium","soloQ":4,"swf":3,"unlockPriority":"Medium–High","glossaryKeys":["dying-state","anti-slug","aura-reading"],"useCases":["Crawl toward pallets, teammates, or safer pickup locations without sacrificing recovery progress.","Make slugging harder to manage by moving much farther than the Killer expects.","Hide your downed Aura from Killer information effects while staying quieter."],"counters":["Provides no ability to fully stand up by itself.","Immediate Killer pickups can deny nearly all value.","Open terrain may offer little useful destination even with faster crawling."],"pros":["9.5 restored simultaneous crawl-and-recovery functionality.","50% Dying-State Haste is substantial.","Combines mobility, recovery, quieter audio, and Aura denial."],"cons":["Entirely slugging-dependent.","Does not finish the self-recovery.","Can be irrelevant if the Killer hooks immediately."],"analysis":["Tenacity ranks this position because its current version is much healthier than older memories of the perk. You can once again recover while crawling, and Tier III provides 50% Haste in the Dying State, letting you relocate without choosing between movement and recovery.","That matters around pallets and teammates. A downed Survivor can move into a position where a teammate has a realistic save while still building recovery progress, or crawl away from a dangerous hook area before the Killer returns.","The quieter pain sounds and Aura denial make the relocation harder to track. Those secondary effects are not enough to carry the perk alone, but they support its central anti-slug purpose cleanly.","Tenacity stays in B because it cannot create its own full recovery. It is excellent support for Unbreakable, Power Struggle, Flip-Flop, or teammate pickups, but a Killer who simply hooks you immediately bypasses the entire package."],"verdict":"A much better anti-slug utility perk after its 9.5 restoration. Tenacity makes the ground phase productive, but still needs another effect or teammate to actually get you standing.","publicationStatus":"published","tags":[],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"David Tapp"},"synergyPerkIds":["unbreakable","flip-flop","power-struggle","soul-guard"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:audit-partial-plus-normalized"],"synergies":["Unbreakable","Flip-Flop","Power Struggle","Soul Guard"],"antiSynergies":[],"name":"Tenacity","alternateName":null,"source":"David Tapp","status":"Live 10.2.0","currentEffect":"While in the Dying State, you can recover while crawling, gain 30/40/50% Haste, have your Grunts of Pain reduced by 75%, and your Aura cannot be read.","activation":["Be in the Dying State.","Ends/deactivates when: The effects end when you leave the Dying State."],"patchNote":"Latest live balance change (9.3.0): Re-added recovery while crawling and restored Haste to 30/40/50% (was 15/20/25% from 9.2.0).","plainEnglishSummary":"While downed, lets you crawl and recover at once, move faster, make less pain noise, and hide your Aura.","cooldown":null,"duration":[],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":["Haste"],"specialInteractions":["Allows recovery while crawling; blocks Aura reading while in the Dying State."],"sourceCharacter":"David Tapp","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"breakdown","rank":111,"tier":"B","roles":["Rescue","Anti-Tunnel","Information"],"summary":"Whenever you are unhooked, destroy that Hook for 180 seconds and reveal the Killer's Aura to yourself for up to 6 seconds.","metaStatus":"Good","skillLevel":"Low","soloQ":3,"swf":4,"unlockPriority":"Medium–High","glossaryKeys":["hook-state","aura-reading","anti-tunnel"],"useCases":["Create a temporary hook dead zone around the place you were rescued.","Use the Killer Aura read to route safely after the unhook.","Stack multiple copies or sabotage tools to make nearby future carries substantially harder."],"counters":["The Killer may have another hook within easy carrying distance.","The hook destruction matters only after you have already been hooked there.","Some maps have enough dense hook coverage that removing one hook changes little."],"pros":["Natural activation with no extra input.","Three-minute hook removal is extremely long.","Includes useful post-unhook Killer information."],"cons":["Map- and hook-layout dependent.","Requires first being hooked.","Can encourage anti-carry strategies that provoke slugging instead."],"analysis":["Breakdown ranks high in this band because 180 seconds is long enough for a destroyed hook to affect multiple later carries. Unlike a temporary sabotage, the hook remains unavailable through a large portion of the match after a completely natural unhook trigger.","The six-second Killer Aura read gives the perk independent post-unhook value even if the hook removal never matters. It helps the rescued Survivor understand whether the Killer is returning, rotating away, or cutting off an escape route.","The ceiling rises sharply when the map already has awkward hook spacing or when teammates also bring Breakout and Saboteur. Removing a key hook can force long carry routes, create pallet-save opportunities, or convince the Killer to abandon a pickup.","The ranking stays in B because hook density is outside the Survivor's control. Some maps give the Killer another hook a few steps away. Breakdown is easy to use and occasionally vicious, but not consistently decisive."],"verdict":"An underrated hook-denial perk with a useful information bonus. Breakdown can quietly ruin a carry zone for three full minutes, but map geometry decides how painful that really is.","publicationStatus":"published","tags":["Hook Denial"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Jeff Johansen"},"synergyPerkIds":["saboteur","breakout","boil-over","off-the-record"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Saboteur","Breakout","Boil Over","Off the Record"],"antiSynergies":[],"name":"Breakdown","alternateName":null,"source":"Jeff Johansen","status":"Live 10.2.0","currentEffect":"When you are unhooked by any means, that Hook breaks and the Killer's Aura is revealed to you for 4/5/6 seconds. The Hook repairs itself after 180 seconds.","activation":["Be unhooked by any means.","Ends/deactivates when: Killer Aura reveal ends after 4/5/6 seconds.","Ends/deactivates when: Hook repairs after 180 seconds."],"patchNote":"Latest live balance change (9.3.2): Reverted to the break-on-unhook version (Killer Aura 4/5/6 s, Hook repairs after 180 s) after the perk was disabled in 9.3.0.","plainEnglishSummary":"Being unhooked breaks the Hook temporarily and briefly reveals the Killer.","cooldown":null,"duration":["Killer Aura reveal: 4/5/6 seconds.","Hook auto-repair: 180 seconds."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["Broken Hook cannot be used until repaired."],"sourceCharacter":"Jeff Johansen","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"vigil","rank":112,"tier":"C","roles":["Exhaustion","Team Support","Recovery"],"summary":"You and nearby Survivors recover from Exhausted 20/25/30% faster, with a 15-second linger after leaving your range.","metaStatus":"Situational","skillLevel":"Low","soloQ":2,"swf":3,"unlockPriority":"Low","glossaryKeys":["exhausted","swf"],"useCases":["Bring Sprint Burst, Lithe, Dead Hard, Dramaturgy, or another Exhaustion perk back online sooner between chases.","Accelerate teammate Exhaustion recovery while repairing or healing together.","Use the 15-second linger so allies keep the benefit after rotating away."],"counters":["The current live version affects Exhausted only, not the broader status-effect list older versions covered.","It provides no value to Survivors who are not using an Exhaustion perk or have not recently triggered one.","Recovery still depends on the normal Exhaustion rules rather than instantly clearing the status."],"pros":["Passive and easy to benefit from.","Can support several teammates from one perk slot.","Pairs with some of the strongest chase perks in the game."],"cons":["Much narrower after the 10.1-era change to Exhausted-only recovery.","Does nothing until an Exhaustion perk has actually been used.","Less valuable in builds with no Exhaustion perk."],"analysis":["Vigil lands at this position because Exhaustion perks remain among the strongest Survivor tools, and reducing their downtime is inherently valuable. The effect applies to the user and teammates within 16 metres, then lingers for 15 seconds, so one copy can support several strong chase perks during ordinary group interactions.","The key correction for the current patch is scope. Older versions and community memory often treat Vigil as a broad status-recovery perk. Our audited 10.2.0 mechanics correctly restrict the live effect to Exhausted. That is a meaningful loss of flexibility and the main reason we rank it lower than some current community lists.","Even with that narrower purpose, the synergy is excellent. Sprint Burst users can return to a ready state sooner, Dead Hard and Lithe users shorten the time between possible activations, and SWF teammates can intentionally recover near the Vigil user before splitting. The effect asks for no button press or special event beyond ordinary proximity.","Vigil is therefore a strong support multiplier rather than a standalone power perk. If nobody in the relevant area is Exhausted, it is invisible. If several players are cycling elite Exhaustion perks, its value compounds. That makes it a narrow support multiplier rather than a general-purpose power perk."],"verdict":"Narrow Exhaustion support after the 10.1 reductions. Useful in proximity-heavy Exhaustion packages, but not a general-purpose default.","publicationStatus":"published","tags":["Support"],"queueRatingStatus":"reviewed","rankRange":[100,125],"rankConfidence":"Medium","rankStatus":"stable","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Quentin Smith"},"synergyPerkIds":["sprint-burst","dead-hard","lithe","dramaturgy"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","rank-review-applied","queue-rating:audit-partial-plus-normalized"],"synergies":["Sprint Burst","Dead Hard","Lithe","Dramaturgy"],"antiSynergies":[],"name":"Vigil","alternateName":null,"source":"Quentin Smith","status":"Live 10.2.0","currentEffect":"You and all Survivors within 16 metres recover from Exhausted 20/25/30% faster. The effect lingers for 15 seconds after leaving the area. A Survivor can only benefit from one Vigil effect at a time.","activation":["A Survivor must be within 16 metres of the perk user while recovering from Exhausted.","Ends/deactivates when: The aura of the effect ends 15 seconds after leaving the perk user's 16 m area."],"patchNote":"Latest live balance change (10.1.2): Bug fix restricting Vigil to Exhausted only. Current 20/25/30% value was set in 10.1.1 (reduced from 30/35/40% in 10.1.0); 10.2.0 made no balance change to these values.","plainEnglishSummary":"Speeds Exhausted recovery by 20/25/30% for you and nearby teammates, with a 15-second linger after leaving range.","cooldown":null,"duration":["Area effect lingers for 15 seconds after a Survivor leaves 16 m range."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":"A Survivor can benefit from only one Vigil effect at a time.","statusEffectsInvolved":["Exhausted"],"specialInteractions":["Applies to the perk user and nearby Survivors; duplicate Vigil effects do not stack."],"sourceCharacter":"Quentin Smith","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"pharmacy","rank":113,"tier":"C","roles":["Item","Healing"],"summary":"Unlock chests much faster and quieter, and every completed unlock guarantees an Emergency Med-Kit.","metaStatus":"Situational","skillLevel":"Low","soloQ":3,"swf":2,"unlockPriority":"Medium","glossaryKeys":["reset"],"useCases":["Guarantee access to a healing Item without bringing one into the Trial.","Open chests quickly enough that the looting detour is less expensive.","Use multiple unopened chests to create additional Emergency Med-Kits for the team."],"counters":["Requires finding unopened chests.","A brought Med-Kit avoids the entire search-and-unlock detour.","Chest time is still time not spent repairing generators."],"pros":["Guaranteed useful item rather than random loot.","125% faster Tier III chest unlocks are quick.","Noise reduction makes looting safer."],"cons":["Chest-dependent.","Uses time to acquire a resource that can simply be brought from the lobby.","Lower value when the team already has healing Items."],"analysis":["Pharmacy ranks in C/B boundary because the perk guarantees something useful rather than gambling on chest RNG. An Emergency Med-Kit has clear practical value, and the large chest-opening speed bonus significantly reduces the normal looting tax.","The perk is most attractive when the Survivor intentionally enters without a Med-Kit or wants to generate additional team healing resources from the map. Plunderer's Instinct and Appraisal can turn that into a broader chest-economy build.","The obvious comparison is the pregame loadout. If you already own a strong Med-Kit, bringing it directly is faster and costs no perk slot. Pharmacy must justify both the slot and the travel to an unopened chest.","That makes it useful resource generation rather than competitive general value. It does its job reliably, but the job itself is optional.","The 10.2 version also supports rummaging, which strengthens its role inside chest and item-economy builds."],"verdict":"A reliable way to turn a chest into a Med-Kit quickly. Pharmacy is good at solving an Item problem that many players can solve before the Trial even begins.","publicationStatus":"published","reviewFlags":["10.2-live-change","v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"tags":["Chest"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Quentin Smith"},"synergyPerkIds":["plunderers-instinct","streetwise","appraisal","moment-of-glory"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"synergies":["Plunderer's Instinct","Streetwise","Appraisal","Moment of Glory"],"antiSynergies":[],"name":"Pharmacy","alternateName":null,"source":"Quentin Smith","status":"Live 10.2.0","currentEffect":"Whenever you unlock a Chest, it contains a Rare Med-Kit. You unlock and rummage Chests 75/100/125% faster, you can rummage each Chest once, and the range at which the Killer hears you unlocking Chests is reduced by 12 metres.","activation":["Unlock a Chest for the guaranteed Rare Med-Kit.","Unlock or rummage a Chest for the tiered interaction-speed bonus.","Ends/deactivates when: The interaction-speed bonus applies only during Chest unlocking or rummaging."],"patchNote":"Latest live balance change (10.2.0): Expanded the 75/100/125% speed bonus to rummaging and added one rummage per Chest; the Rare Med-Kit guarantee and the 12-metre sound reduction remain.","plainEnglishSummary":"Chests provide a Rare Med-Kit, can be opened and rummaged much faster, and can each be rummaged once while your unlocking noises carry less far.","cooldown":null,"duration":["Applies during each qualifying Chest interaction."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":"Each Chest can be rummaged once.","statusEffectsInvolved":[],"specialInteractions":["The authoritative 10.2.0 notes specify 'a Rare Med-Kit'; the record does not assume a more specific Med-Kit identity."],"sourceCharacter":"Quentin Smith","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"overzealous","rank":114,"tier":"C","roles":["Objective","Totem"],"summary":"After cleansing or blessing a Totem, repair 10% faster; cleansing a Hex doubles the bonus to 20% until you lose a Health State.","metaStatus":"Situational","skillLevel":"Low–Medium","soloQ":2,"swf":2,"unlockPriority":"Medium–High","glossaryKeys":["pressure","health-state"],"useCases":["Convert a necessary Hex cleanse into a powerful objective-speed buff.","Use a Dull Totem for a reliable 10% repair bonus when you expect a long safe generator window.","Stack the repair bonus with objective-information perks so the speed goes onto an important generator."],"counters":["Losing a Health State ends the bonus immediately.","Totem setup time can offset the repair time saved.","Using a Dull Totem may conflict with Boon strategies."],"pros":["10% repair speed is meaningful; 20% after a Hex is excellent.","No cooldown once activated.","Naturally rewards useful Hex cleansing."],"cons":["Requires Totem interaction first.","Fragile to any Health-State loss.","Can waste team Totem resources."],"analysis":["Overzealous ranks this position because ten percent repair speed is a legitimate objective bonus, and the twenty-percent Hex version is much stronger than many players remember. If you were going to cleanse a dangerous Hex anyway, the repair boost is almost pure upside.","The Dull Totem version is more complicated. Time spent finding and cleansing the Totem must eventually be repaid through faster generator work, so the perk needs a reasonably long safe repair window to become efficient.","Its biggest weakness is fragility. Any Health-State loss ends the effect, which means the Killer can erase the entire setup with one successful hit. Skilled positioning and good information therefore improve Overzealous more than its simple text suggests.","It remains B because setup plus fragility make the average value inconsistent. Against the right Hex build, however, a twenty-percent repair bonus can easily make the perk look much stronger."],"verdict":"A strong objective reward for Totem interaction, especially against Hexes. Overzealous has excellent numbers, but one hit can erase all the setup.","publicationStatus":"published","tags":["Repair Speed"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Haddie Kaur"},"synergyPerkIds":["deja-vu","counterforce","resilience"],"synergyOther":["Boon perks"],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Déjà Vu","Counterforce","Resilience","Boon perks"],"antiSynergies":[],"name":"Overzealous","alternateName":null,"source":"Haddie Kaur","status":"Live 10.2.0","currentEffect":"After you cleanse or bless a Totem, Overzealous activates and increases your Generator repair speed by 8/9/10%. The bonus is doubled to 16/18/20% when the activation is from cleansing a Hex Totem. It deactivates after you lose a Health State by any means.","activation":["Cleanse or bless a Totem.","Ends/deactivates when: Losing a Health State by any means."],"patchNote":"Latest live balance change (6.7.0): Raised the repair bonus to 8/9/10% from 6/7/8% and enabled activation from blessing a Totem; the Hex Totem bonus remains double.","plainEnglishSummary":"Cleansing or blessing a Totem speeds up your repairs until you lose a Health State, with a doubled bonus for cleansing a Hex Totem.","cooldown":null,"duration":["Active until you lose a Health State or the Trial ends."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["Cleansing a Hex Totem doubles the repair-speed bonus; cleansing a Dull Totem or blessing a Totem applies the normal bonus."],"sourceCharacter":"Haddie Kaur","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"plunderers-instinct","rank":115,"tier":"C","roles":["Item","Information"],"summary":"See Chests and dropped Items without the old range limit, open Chests up to 200% faster, and improve higher-rarity Item odds by 50%.","metaStatus":"Situational","skillLevel":"Low","soloQ":3,"swf":2,"unlockPriority":"Medium","glossaryKeys":["aura-reading"],"useCases":["Locate every relevant chest/item resource quickly.","Open Chests fast enough that a loot detour costs far less time than before.","Drive Appraisal, Ace in the Hole, Pharmacy, and other chest builds."],"counters":["Loot is still random.","Chest value competes with generator time.","A strong brought Item can make the whole chest economy unnecessary."],"pros":["10.2 removed the old Aura range restriction.","200% faster Chest unlocking is enormous.","Higher-rarity chance improves the average Item roll."],"cons":["Still a side-objective perk.","Cannot guarantee the Item category you need.","Low value if the team already entered with premium Items."],"analysis":["Plunderer’s Instinct is another 10.2 perk that should not inherit its old reputation. The Aura range restriction is gone and Chest opening can be 200% faster at Tier III, substantially reducing the time cost of the entire loot strategy.","The 50% higher-rarity modifier remains, so the perk now combines map-wide resource information, dramatically faster acquisition, and better average quality in one slot.","That does not make Chests the main objective. Random Items still have to repay travel and interaction time, and a lobby that already brought strong equipment has less reason to loot.","The live version deserves a meaningful promotion among specialist perks. It is still a chest perk, but it is finally an extremely efficient chest perk."],"verdict":"A serious chest-build perk after 10.2. Global resource information and 200% faster opening make looting far less embarrassing to the team’s generator clock.","publicationStatus":"published","reviewFlags":["10.2-live-change","v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"tags":["Chest"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"general","sourceCharacter":"General"},"synergyPerkIds":["appraisal","ace-in-the-hole","pharmacy","streetwise"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"synergies":["Appraisal","Ace in the Hole","Pharmacy","Streetwise"],"antiSynergies":[],"name":"Plunderer's Instinct","alternateName":null,"source":"General perk","status":"Live 10.2.0","currentEffect":"You see the Auras of Chests and Items. You unlock Chests 150/175/200% faster. Whenever you unlock a Chest, you are 50% more likely to find an Item of higher rarity.","activation":["Aura reading is passive.","Unlock a Chest for the speed and higher-rarity Item effects.","Ends/deactivates when: The speed and rarity effects apply to Chest unlocking; the 10.2.0 notes do not extend the rarity trigger to rummaging."],"patchNote":"Latest live balance change (10.2.0): Removed the 32/48/64-metre Aura limit, added 150/175/200% faster Chest unlocking, and tied the 50% higher-rarity Item chance to Chest unlocking.","plainEnglishSummary":"See Chests and Items without the former range limit, open Chests dramatically faster, and improve the chance of a higher-rarity Item when unlocking one.","cooldown":null,"duration":[],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["The former 32/48/64-metre Aura range was removed.","The higher-rarity chance is tied to unlocking a Chest."],"sourceCharacter":"General","isGeneralPerk":true,"currentLivePatchVerified":"10.2.0"},{"id":"inner-focus","rank":116,"tier":"C","roles":["Information"],"summary":"Always see teammates' Scratch Marks; whenever the Killer makes another Survivor lose a Health State, see the Killer for up to 10 seconds.","metaStatus":"Situational","skillLevel":"Low","soloQ":4,"swf":2,"unlockPriority":"Medium–High","glossaryKeys":["aura-reading","solo-q","health-state"],"useCases":["Track where teammate chases are moving through their Scratch Marks.","Gain a long Killer Aura read every time another Survivor loses a Health State.","Use the hit-triggered Aura to judge whether the Killer is continuing chase or rotating."],"counters":["Provides no Aura trigger when you are the Survivor losing the Health State.","Team Scratch Marks can add visual clutter.","Stealth and Aura-blocking Killer effects can deny the read."],"pros":["Ten-second Killer Aura reads are long.","Natural trigger occurs frequently in normal matches.","Excellent Solo Q chase-location information."],"cons":["No direct action-speed benefit.","Does less while you are the primary chase target.","Can be visually noisy."],"analysis":["Inner Focus earns this position because a ten-second Killer Aura reveal after a teammate loses a Health State is a substantial information window. Hits are among the most common events in the game, so the perk receives opportunities without demanding unusual setup.","The permanent teammate Scratch Marks add another layer. They can tell you where a teammate recently ran even after their Aura disappears, helping infer chase paths or avoid colliding with another Survivor's pressure.","Solo Q benefits more than SWF because the perk supplies information a coordinated team can often communicate verbally. Even in SWF, a ten-second Killer Aura is more precise than a callout.","It remains in B because the information is mostly reactive. You gain knowledge after the Killer has already created pressure, and the perk offers no direct way to stop the next hit."],"verdict":"A strong reactive information perk. Inner Focus gives long Killer reads off normal match events and is especially useful when Solo Q lacks chase callouts.","publicationStatus":"published","tags":["Aura Reading","Team Tracking"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Haddie Kaur"},"synergyPerkIds":["eyes-of-belmont","empathy","alert","bond"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:audit-partial-plus-normalized"],"synergies":["Eyes of Belmont","Empathy","Alert","Bond"],"antiSynergies":[],"name":"Inner Focus","alternateName":null,"source":"Haddie Kaur","status":"Live 10.2.0","currentEffect":"You can always see other Survivors' Scratch Marks. Whenever another Survivor loses a Health State due to the Killer, the Killer's Aura is revealed to you for 6/8/10 seconds, depending on perk tier.","activation":["Scratch Mark visibility is continuously available during the Trial.","For the Killer Aura reveal, another Survivor must lose a Health State due to the Killer."],"patchNote":"Latest live balance change (8.3.2): The Killer Aura reveal now triggers only from Health State loss caused by the Killer; 8.3.0 had increased the reveal duration to 6/8/10 seconds and removed its 32 m condition.","plainEnglishSummary":"It shows teammates' Scratch Marks and briefly reveals the Killer when the Killer causes a teammate to lose a Health State.","cooldown":null,"duration":["Killer Aura reveal: 6/8/10 seconds per qualifying event."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":[],"sourceCharacter":"Haddie Kaur","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"calm-spirit","rank":117,"tier":"C","roles":["Stealth","Totem"],"summary":"Never scream or scare Crows, and perform silent Totem and Chest interactions up to 10% faster instead of slower.","metaStatus":"Situational","skillLevel":"Low","soloQ":3,"swf":3,"unlockPriority":"Low–Medium","glossaryKeys":["pressure"],"useCases":["Hard-counter Killer perks and powers that rely on Survivor screams for information.","Move near Crows with much lower risk of creating a visible disturbance.","Interact with chests or Totems silently when stealth matters more than speed."],"counters":["Provides little value in matches without meaningful scream or Crow interactions.","The side-objective speed bonus is small and does not make Chests or Totems efficient by itself."],"pros":["Complete scream suppression is a genuine hard counter.","Passive with no cooldown.","Also reduces environmental Crow information."],"cons":["Matchup-dependent against Killers and perks that do not use screams or Crows.","Its 8/9/10% interaction-speed bonus is useful but modest."],"analysis":["Calm Spirit received a simple but important repair in 10.2: the old interaction-speed penalty is gone. Totem blessing/cleansing and Chest unlocking are now silent and up to 10% faster instead of up to 30% slower.","That removes the worst feeling attached to the perk. Scream immunity is still matchup-dependent, but you no longer pay a universal side-objective tax just for bringing the counter.","Against scream-heavy Killers and information perks, complete scream suppression can deny valuable tracking. Crow immunity remains a smaller but occasionally useful environmental benefit.","The buff does not make Calm Spirit universal, but it raises the floor enough that its old near-bottom ranking is no longer appropriate without review."],"verdict":"No longer punishes you for equipping it. Calm Spirit is still a matchup counter, but 10.2 turned its silent side interactions from a tax into a small bonus.","publicationStatus":"published","reviewFlags":["10.2-live-change","v15-schema-migrated","rank-review-applied","queue-rating:audit-explicit"],"tags":["Scream Suppression"],"queueRatingStatus":"reviewed","rankRange":[108,130],"rankConfidence":"Low","rankStatus":"stable","evidenceStatus":"strong-inference","acquisition":{"type":"character","sourceCharacter":"Jake Park"},"synergyPerkIds":["distortion","iron-will","light-footed"],"synergyOther":[],"antiSynergyPerkIds":["hardened"],"archetypeRatings":[],"synergies":["Distortion","Iron Will","Light-Footed"],"antiSynergies":["Hardened"],"name":"Calm Spirit","alternateName":null,"source":"Jake Park","status":"Live 10.2.0","currentEffect":"You do not scare Crows or scream. You Bless and Cleanse Totems and unlock Chests silently and 8/9/10% faster.","activation":[],"patchNote":"Latest live balance change (10.2.0): Replaced the 40/35/30% interaction slowdown with an 8/9/10% speed bonus for silent Blessing, Cleansing, and Chest Unlocking; Crow and scream suppression remain.","plainEnglishSummary":"Suppresses Crow alerts and screams, and makes Totem and Chest interactions silent and faster.","cooldown":null,"duration":["The Crow and scream suppression is passive; the interaction bonus applies while Blessing, Cleansing, or unlocking a Chest."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["Blessing, Cleansing, and Chest Unlocking are silent while affected by Calm Spirit."],"sourceCharacter":"Jake Park","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"stake-out","rank":118,"tier":"C","roles":["Objective","Skill Check","Utility"],"summary":"Hide near the Killer inside their Terror Radius to bank Tokens, then spend each Token on a harder special Skill Check worth +4% progress.","metaStatus":"Situational","skillLevel":"Medium","soloQ":2,"swf":2,"unlockPriority":"High","glossaryKeys":["terror-radius","pressure"],"useCases":["Bank Tokens while safely hidden near a Killer pressure zone.","Cash Tokens on generators for +4% progress per successful special Skill Check.","Use up to four stocked Tokens as a burst-progress resource later."],"counters":["The special Skill Check is intentionally harder than a normal basic check.","The checks no longer trigger Hyperfocus or other Skill Check perks.","Charging requires 15 seconds hidden within 24 metres of the Killer while in the Terror Radius."],"pros":["Up to four +4% progress checks can create meaningful objective value.","No longer depends on converting Good checks into Greats.","Can bank value for later."],"cons":["Lost the famous Hyperfocus synergy.","Charging Tokens asks you to spend time near danger while hidden.","Missing still spends the Token."],"analysis":["Stake Out was fundamentally rebuilt in 10.2. The old Good-to-Great conversion, and with it the classic Hyperfocus safety net, is gone. The perk now creates its own special Skill Checks worth +4% progress.","The new ceiling is still interesting. Four banked Tokens can represent a large burst of bonus progress if you successfully hit all four special checks, giving the perk independent objective value instead of merely supporting another perk.","The trade is difficulty and setup. Tokens require hiding close to the Killer inside the Terror Radius, and the special checks are intentionally harder and no longer activate other Skill Check perks.","This version deserves a completely fresh rank rather than inheriting the old Hyperfocus-based evaluation. It is now a standalone risk-and-reward objective perk."],"verdict":"No longer Hyperfocus glue. Modern Stake Out banks dangerous proximity into harder +4% progress checks, giving it its own ceiling and its own execution risk.","publicationStatus":"published","reviewFlags":["10.2-live-change","v15-schema-migrated","rank-review-applied","queue-rating:audit-explicit"],"tags":["Risk Reward"],"queueRatingStatus":"reviewed","rankRange":[105,132],"rankConfidence":"Medium","rankStatus":"stable","evidenceStatus":"needs-controlled-testing","acquisition":{"type":"character","sourceCharacter":"David Tapp"},"synergyPerkIds":["deja-vu","resilience"],"synergyOther":["Stealth-oriented play that naturally banks safe Terror Radius time"],"antiSynergyPerkIds":["fast-track","fogwise","hyperfocus","road-life","scavenger","specialist"],"archetypeRatings":[],"synergies":["Déjà Vu","Resilience","Stealth-oriented play that naturally banks safe Terror Radius time"],"antiSynergies":["Fast Track","Fogwise","Hyperfocus","Road Life","Scavenger","Specialist"],"name":"Stake Out","alternateName":null,"source":"David Tapp","status":"Live 10.2.0","currentEffect":"After hiding for 15 seconds within 24 metres of the Killer while inside their Terror Radius, gain 1 Token, up to 2/3/4. While you have at least 1 Token, basic Skill Checks are replaced by special Skill Checks. Special Skill Checks grant 4% more progress, and hitting or missing one spends 1 Token.","activation":["Hide for 15 seconds while within 24 metres of the Killer and inside the Killer's Terror Radius to gain a Token.","Have at least 1 Token for basic Skill Checks to become special Skill Checks.","Ends/deactivates when: Hitting or missing a special Skill Check consumes 1 Token.","Ends/deactivates when: Without a Token, basic Skill Checks are no longer replaced by Stake Out's special Skill Checks."],"patchNote":"Latest live balance change (10.2.0): Complete rework: hiding 15 seconds within 24 metres of the Killer while in the Terror Radius earns Tokens; Tokens replace basic Skill Checks with special +4%-progress checks and are spent on hit or miss.","plainEnglishSummary":"Hide near the Killer inside the Terror Radius to build tokens that turn basic Skill Checks into special +4%-progress checks.","cooldown":null,"duration":["Hiding requirement: 15 seconds for each Token earned."],"tokenOrStackBehavior":"Gain 1 Token after meeting the 15-second hiding condition, up to 2/3/4. Each hit or missed special Skill Check spends 1 Token.","oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["Stake Out's special Skill Checks grant +4% progress.","The final live release removed the PTB's additional progression penalty for missing a special Skill Check.","10.2.0 fixed token-consumption issues so tokens are not incorrectly spent by unrelated Special Skill Checks and are correctly updated when a basic Skill Check interaction is interrupted.","Stake Out's special Skill Checks do not activate other Skill Check perks."],"sourceCharacter":"David Tapp","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"premonition","rank":119,"tier":"C","roles":["Information"],"summary":"While not in chase, looking toward a Killer within 32 metres gives a warning and reveals their Aura for 3 seconds.","metaStatus":"Situational","skillLevel":"Low","soloQ":3,"swf":3,"unlockPriority":"Low–Medium","glossaryKeys":["aura-reading"],"useCases":["Check whether a nearby Killer is actually on the side of the structure you suspect.","Get a short Aura confirmation before committing to a generator or rescue.","Detect nearby stealth Killers when the trigger conditions are satisfied."],"counters":["It does not trigger while you are already in chase.","A 45-second Tier III cooldown is long.","Three seconds of Aura information is modest compared with stronger information perks."],"pros":["Now gives real Killer Aura information.","Simple warning for Solo Q and newer players.","Can help against nearby stealth approaches."],"cons":["Long cooldown.","No direct chase power.","Outclassed by broader Aura perks."],"analysis":["Premonition received the rework it needed. Instead of a vague directional ping on a short cooldown, the live 10.2 version gives a clear notification and three seconds of Killer Aura when you look toward a nearby Killer outside chase.","That makes the information much easier to act on. A short Aura is enough to confirm which side of a wall the Killer occupies or whether a suspicious approach is real.","The forty-five-second Tier III cooldown is the limiting factor, and the perk shuts off in chase where Killer information often matters most.","Premonition is therefore improved beginner and Solo Q awareness, not a top information perk. It finally answers a concrete question instead of merely making the player nervous."],"verdict":"Much healthier in 10.2: a real three-second Aura read instead of a cryptic ping. Useful awareness, still limited by a long cooldown and no chase activation.","publicationStatus":"published","reviewFlags":["10.2-live-change","v15-schema-migrated","queue-rating:audit-explicit"],"tags":["Awareness","Aura Reading"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"general","sourceCharacter":"General"},"synergyPerkIds":["eyes-of-belmont","dark-sense","kindred","bond"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"synergies":["Eyes of Belmont","Dark Sense","Kindred","Bond"],"antiSynergies":[],"name":"Premonition","alternateName":null,"source":"General perk","status":"Live 10.2.0","currentEffect":"While not being chased by the Killer, whenever you look in the Killer's direction within 32 metres, you are notified and see the Killer's Aura for 3 seconds. Cooldown: 55/50/45 seconds.","activation":["You are not being chased.","Look in the Killer's direction while they are within 32 metres.","Ends/deactivates when: The Aura reveal ends after 3 seconds.","Ends/deactivates when: The perk cannot trigger during its 55/50/45-second cooldown or while you are being chased."],"patchNote":"Latest live balance change (10.2.0): Reworked to trigger while not chased when looking toward the Killer within 32 metres, reveal the Killer's Aura for 3 seconds, and use a 55/50/45-second cooldown.","plainEnglishSummary":"Outside chase, looking toward a nearby Killer gives a notification and a brief Aura reveal.","cooldown":"55/50/45 seconds.","duration":["Killer Aura reveal: 3 seconds."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["The former 45-degree detection-cone field is removed; final 10.2.0 live text uses 'look in the Killer's direction'."],"sourceCharacter":"General","isGeneralPerk":true,"currentLivePatchVerified":"10.2.0"},{"id":"better-together","rank":120,"tier":"C","roles":["Objective","Information"],"summary":"While you repair a generator, teammates see its Aura; if the Killer downs another Survivor during that repair, you see every teammate for up to 30 seconds.","metaStatus":"Situational","skillLevel":"Low","soloQ":3,"swf":1,"unlockPriority":"Medium","glossaryKeys":["aura-reading","solo-q","pressure"],"useCases":["Tell Solo Q teammates exactly which generator you are working on.","Use the post-down team Aura read to decide whether you should rescue, stay on the generator, or rotate.","Reduce accidental generator duplication and improve rescue responsibility."],"counters":["The generator Aura provides information rather than a speed bonus.","The teamwide Aura read only triggers if another Survivor is downed while you are repairing.","Voice-coordinated groups can communicate much of the same information."],"pros":["Very clean Solo Q communication.","Thirty-second teammate Aura read is long.","Activates through normal generator play."],"cons":["Little direct mechanical power.","Lower value in SWF.","Does not show the Killer."],"analysis":["Better Together earns a surprisingly healthy position because it solves two common Solo Q information problems through the action Survivors should already be doing. Teammates know which generator you are repairing, helping them decide whether to join, spread out, or avoid dragging a chase into that area.","When another Survivor is downed during your repair, the second effect reveals every teammate for up to thirty seconds. That can immediately identify whether someone is already moving for the pickup or hook, allowing you to remain productive instead of duplicating the rescue.","The perk is much less exciting in coordinated voice chat. A SWF can announce the generator and rescue rotation without paying a perk slot, which makes Better Together primarily a Solo Q quality-of-life tool.","It stays in B because information improves decisions but does not directly speed generators or extend chases. Still, the information is practical, repeatable, and attached to productive play rather than a side quest."],"verdict":"A simple but useful Solo Q communication perk. Better Together makes your generator visible and helps prevent the classic three-people-left-their-gens-for-one-down problem.","publicationStatus":"published","tags":["Solo Q"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Nancy Wheeler"},"synergyPerkIds":["prove-thyself","deja-vu","kindred","teamwork-full-circuit"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:audit-partial-plus-normalized"],"synergies":["Prove Thyself","Déjà Vu","Kindred","Teamwork: Full Circuit"],"antiSynergies":[],"name":"Better Together","alternateName":null,"source":"Nancy Wheeler","status":"Live 10.2.0","currentEffect":"While you repair a Generator, its Aura is revealed to all other Survivors. If the Killer downs another Survivor while you repair a Generator, the Auras of all other Survivors are revealed to you for 20/25/30 seconds.","activation":["Repair a Generator to reveal its Aura to others.","Killer downs another Survivor while you are repairing for the tiered Aura reveal.","Ends/deactivates when: The post-down Aura reveal ends after 20/25/30 seconds.","Ends/deactivates when: Generator Aura is shown while you repair it."],"patchNote":"Latest live balance change (9.5.0): Clarified that Plot Twist cannot trigger the down effect; 9.1.0 had previously removed the Generator Aura range limit and set the tiered duration.","plainEnglishSummary":"Teammates see the Generator you repair, and a Killer down while you repair reveals teammates to you.","cooldown":null,"duration":["Other Survivor Aura reveal: 20/25/30 seconds by tier."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["Plot Twist cannot trigger the down effect."],"sourceCharacter":"Nancy Wheeler","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"cut-loose","rank":121,"tier":"C","roles":["Chase","Stealth"],"summary":"After a rushed vault in chase, your rushed vaults become silent for up to 6 seconds; additional rushed vaults refresh the timer before a 45-second cooldown.","metaStatus":"Situational","skillLevel":"High","soloQ":2,"swf":2,"unlockPriority":"Medium–High","glossaryKeys":["looping"],"useCases":["Chain silent vaults around structures where the Killer relies on audio through walls.","Break line of sight after the first vault and use later silent vaults to disguise your route.","Pair with other vault perks to create layered chase mindgames."],"counters":["The first rushed vault still creates normal information before the effect is active.","Direct visual contact makes the missing sound irrelevant.","The perk enters a 45-second cooldown after the active chain ends."],"pros":["Can refresh itself repeatedly during a vault sequence.","Strong on indoor and tall-wall structures.","Does not cause Exhaustion."],"cons":["Requires good chase geometry.","Audio denial is indirect value.","Experienced Killers may infer the vault from pathing anyway."],"analysis":["Cut Loose ranks here because repeated silent vaults can create legitimate chase uncertainty without consuming an Exhaustion slot. Once the first rushed vault activates the perk, every qualifying vault during the window resets the timer, allowing a Survivor to maintain the silence through a sequence of windows.","The effect is strongest when line of sight is already broken. At tall walls or indoor structures, Killers often use the vault sound to decide whether the Survivor committed to the window or doubled back. Removing that cue forces them to verify the route visually.","Quick & Quiet is easier to use for one decisive silent action, while Cut Loose asks for an ongoing chase pattern. Pairing the two can make the first vault silent as well, though spending two slots purely on vault audio is a deliberate specialist build.","Cut Loose remains B because sound denial does not guarantee distance. The Survivor still needs a structure where uncertainty matters and must path intelligently after each vault."],"verdict":"A real chase mindgame perk on the right structures. Cut Loose can make repeated vault routes much harder to read, but the Survivor still has to turn silence into a Killer mistake.","publicationStatus":"published","tags":["Vault","Sound Denial"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Thalita Lyra"},"synergyPerkIds":["quick-quiet","lithe","dance-with-me","finesse"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Quick & Quiet","Lithe","Dance With Me","Finesse"],"antiSynergies":[],"name":"Cut Loose","alternateName":null,"source":"Thalita Lyra","status":"Live 10.2.0","currentEffect":"After performing a Rushed Vault while in chase, Cut Loose activates for 4/5/6 seconds. During that time, Rushed Vaults create no sound or Killer notification; each Rushed Vault resets the timer. A 45-second cooldown begins when the effect ends.","activation":["Perform a Rushed Vault while in chase.","Ends/deactivates when: Effect expires after 4/5/6 seconds without another Rushed Vault; a vault resets that timer."],"patchNote":"Latest live balance change (unknown): No material live balance change could be verified from available patch history.","plainEnglishSummary":"Rushed Vaults become silent for a short time after vaulting during chase, with vaults extending the effect.","cooldown":"45 seconds after effect ends","duration":["Effect window: 4/5/6 seconds by tier."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["Suppresses Rushed Vault sound and its Killer notification."],"sourceCharacter":"Thalita Lyra","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"camaraderie","rank":122,"tier":"C","roles":["Rescue","Objective"],"summary":"While you are in the Struggle Phase, a teammate entering within 16 metres pauses your hook timer for up to 34 seconds.","metaStatus":"Situational","skillLevel":"Low","soloQ":2,"swf":3,"unlockPriority":"Medium","glossaryKeys":["hook-state","pressure"],"useCases":["Buy the team extra generator time against a Killer defending your second-stage hook.","Prevent an approaching rescuer from being forced into an immediate bad trade.","Coordinate with Reassurance to stretch a contested hook dramatically."],"counters":["Only works during the Struggle Phase.","A teammate must get within 16 metres before the timer pause begins.","If the Killer leaves the hook and a safe rescue is available, the extra timer may add little."],"pros":["Thirty-four extra hook seconds can be a major macro swing.","Requires no input from the hooked player.","Strong anti-camp team value."],"cons":["Second-hook-stage only.","Needs teammate proximity.","Very low value against Killers who do not defend hooks."],"analysis":["Camaraderie sits in this band because thirty-four paused hook seconds can be extremely valuable against a Killer who is refusing to leave second-stage pressure. Those seconds can become generator progress instead of forcing the team into the immediate trade the Killer wants.","The condition is simple but not automatic. A teammate must enter the sixteen-metre range, which means the team still has to approach the dangerous area before the pause begins. Once triggered, however, the rescuer can retreat or wait for a better opening.","Reassurance creates the obvious strategic pairing. One perk can pause the hook from the rescuer's side and the other adds a separate second-stage delay from the hooked Survivor's loadout, creating a large amount of time for the rest of the team.","Camaraderie remains B because it only matters on second hook and only against meaningful hook defense. In the matches where that problem appears, its value can be far higher than its tiny pick rate suggests."],"verdict":"A potent second-stage anti-camp timer extension. Camaraderie is narrow, but thirty-four seconds is enough time to materially change the team's rescue economics.","publicationStatus":"published","tags":["Anti-Camp","Hook","Time"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Steve Harrington"},"synergyPerkIds":["reassurance","kindred","babysitter","shoulder-the-burden"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Reassurance","Kindred","Babysitter","Shoulder the Burden"],"antiSynergies":[],"name":"Camaraderie","alternateName":null,"source":"Steve Harrington","status":"Live 10.2.0","currentEffect":"While you are hooked in the Struggle Phase, the Hook timer pauses for 26/30/34 seconds when another Survivor enters within 16 metres of you.","activation":["Be hooked in the Struggle Phase.","Another Survivor enters within 16 metres.","Ends/deactivates when: The Hook timer resumes when the tiered pause expires."],"patchNote":"Latest live balance change (unknown): No material live balance change could be verified from available patch history.","plainEnglishSummary":"A teammate coming near you during the Struggle Phase pauses the Hook timer temporarily.","cooldown":null,"duration":["Hook timer pause: 26/30/34 seconds by tier."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":[],"sourceCharacter":"Steve Harrington","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"parental-guidance","rank":123,"tier":"C","roles":["Chase","Stealth"],"summary":"After stunning the Killer by any means, hide your Grunts of Pain, Scratch Marks, and Blood for 7 seconds.","metaStatus":"Situational","skillLevel":"High","soloQ":2,"swf":2,"unlockPriority":"Medium–High","glossaryKeys":["looping"],"useCases":["Turn a pallet or Head On stun into a complete tracking break.","Use the seven-second suppression window to change direction after line of sight is lost.","Pair repeated stun tools with stealth-focused chase builds."],"counters":["Requires successfully stunning the Killer.","Direct vision and Aura reading still reveal you.","Seven seconds disappears quickly if the tile has no branching routes."],"pros":["Suppresses three important tracking channels simultaneously.","Works after any Killer stun, not just pallets.","Can convert a successful stun into an actual chase escape."],"cons":["Stun-dependent.","No raw Haste or health-state protection.","Needs good pathing to capitalize."],"analysis":["Parental Guidance ranks this position because seven seconds without pain sounds, Scratch Marks, or Blood is enough to create a serious tracking problem after a stun. The Killer is already losing time to the stun animation, which gives the Survivor a natural window to break line of sight.","The perk is especially effective with Head On and Smash Hit. One creates a reliable Locker stun opportunity, while the other can add immediate distance after a pallet stun. Parental Guidance then removes the trail that would normally tell the Killer where that distance went.","The ceiling depends on geometry. A Survivor who runs straight down an open lane remains visible regardless of the hidden tracking cues. Dense structures and branching paths are where the suppression actually becomes threatening.","That makes the perk a useful high-skill chase tool. It can turn one won interaction into a complete escape, but it cannot guarantee the stun or the route afterward."],"verdict":"A strong stun-to-stealth converter. Parental Guidance is excellent when you can break line of sight immediately after the Killer loses control of the chase.","publicationStatus":"published","tags":["Tracking Denial","Stun"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Yoichi Asakawa"},"synergyPerkIds":["head-on","smash-hit","quick-quiet","lucky-break"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Head On","Smash Hit","Quick & Quiet","Lucky Break"],"antiSynergies":[],"name":"Parental Guidance","alternateName":null,"source":"Yoichi Asakawa","status":"Live 10.2.0","currentEffect":"After stunning the Killer by any means, suppresses your Grunts of Pain, Scratch Marks, and Pools of Blood for 5/6/7 seconds.","activation":["Stun the Killer by any means.","Ends/deactivates when: The suppression ends after 5/6/7 seconds."],"patchNote":"Latest live balance change (unknown): No material live balance change could be verified from available patch history.","plainEnglishSummary":"Stunning the Killer briefly hides your pain sounds and tracking traces.","cooldown":null,"duration":["Grunts of Pain, Scratch Marks, and Pools of Blood suppression: 5/6/7 seconds."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":[],"sourceCharacter":"Yoichi Asakawa","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"still-sight","rank":124,"tier":"C","roles":["Information"],"summary":"After standing still for 2 seconds at Tier III, see the Killer, nearby generators, and nearby chests within 24 metres until you move.","metaStatus":"Situational","skillLevel":"Low–Medium","soloQ":2,"swf":2,"unlockPriority":"Medium","glossaryKeys":["aura-reading","pressure"],"useCases":["Pause briefly behind cover to check whether the Killer is approaching.","Use the Killer Aura at tall-wall structures where sightlines are poor.","Scout nearby generator and chest positions on unfamiliar maps."],"counters":["You must stop moving to activate it.","The 24-metre radius is local rather than map-wide.","Aura-blocking or Undetectable effects can remove the most valuable information."],"pros":["Only two seconds of stillness at Tier III.","Can show the Killer continuously while you remain stationary.","Also provides local objective information."],"cons":["Standing still costs chase and objective tempo.","Short range.","Easy to misuse by waiting too long for information."],"analysis":["Still Sight takes this position because the current two-second activation is fast enough to be practical in short scouting pauses. Behind a wall or before committing to an unsafe generator, briefly stopping can reveal exactly where the Killer is within the local area.","The perk is also interesting at tall-wall loops where direct sight is poor. If you can safely become stationary for the activation, the Killer Aura can remove a mindgame entirely until you move again.","The obvious problem is tempo. Dead by Daylight rewards movement and objective work, so a perk that asks you to stand still must answer a question worth the lost seconds. Holding the effect unnecessarily can turn useful information into self-inflicted inefficiency.","Still Sight therefore lands in B as a deliberate scouting tool. It is stronger than its low usage implies, but only when the player uses brief information checks rather than treating stillness as a playstyle."],"verdict":"A useful local scouting perk after its faster activation buff. Still Sight rewards short, purposeful pauses, not standing around admiring the Aura colors.","publicationStatus":"published","tags":["Aura Reading","Scouting"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Aestri Yazar"},"synergyPerkIds":["open-handed","eyes-of-belmont","urban-evasion","kindred"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Open-Handed","Eyes of Belmont","Urban Evasion","Kindred"],"antiSynergies":[],"name":"Still Sight","alternateName":null,"source":"Aestri Yazar","status":"Live 10.2.0","currentEffect":"After standing still for 4/3/2 seconds, reveals the Auras of the Killer, Chests, and Generators within 24 m. The effect deactivates when you start moving.","activation":["Stand still for 4/3/2 seconds.","Ends/deactivates when: Moving deactivates the Aura reading."],"patchNote":"Latest live balance change (9.1.0): Reduced activation time to 4/3/2 seconds from 6/5/4 seconds.","plainEnglishSummary":"Standing still briefly reveals nearby Killer, Chest, and Generator Auras until you move.","cooldown":null,"duration":["Aura reading continues while stationary and ends when movement begins."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["Reveals Killer, Chest, and Generator Auras within 24 m."],"sourceCharacter":"Aestri Yazar","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"reactive-healing","rank":125,"tier":"C","roles":["Healing","Information"],"summary":"While injured, a nearby teammate losing a Health State instantly grants up to 50% of your missing healing progress.","metaStatus":"Situational","skillLevel":"Low","soloQ":2,"swf":2,"unlockPriority":"Medium","glossaryKeys":["health-state","reset"],"useCases":["Passively gain healing progress while another nearby Survivor is being pressured.","Combine multiple triggers to approach or complete a heal without spending equivalent healing time.","Pair the free progress with a Med-Kit or teammate heal to finish the remaining portion quickly."],"counters":["You must already be Injured.","Another Survivor must lose a Health State within 32 metres.","The perk does not automatically complete a full heal from a fresh Injured state in one ordinary trigger."],"pros":["Free healing progress with no action time.","Can trigger repeatedly.","Useful in chaotic multi-Survivor pressure situations."],"cons":["Entirely dependent on nearby teammates taking damage.","Does not provide a controlled heal on demand.","Can encourage staying injured while hoping for a trigger."],"analysis":["Reactive Healing ranks this position because free healing progress is always attractive, but the trigger belongs to the Killer and your teammates rather than you. When another Survivor within 32 metres loses a Health State while you are Injured, half of your missing healing progress can appear instantly at Tier III.","That progress is most valuable when it shortens a later interaction. A teammate or Med-Kit only needs to finish the remainder, and repeated triggers can push the bar even farther. In chaotic matches, the perk can quietly save a meaningful amount of reset time.","The downside is control. If the team spreads out well or the Killer chases far away, Reactive Healing may sit idle. If everyone is nearby taking repeated hits, the team already has a larger pressure problem.","It remains B because the perk can be wonderfully efficient without being reliable. Think of it as opportunistic free progress rather than a self-heal plan."],"verdict":"Free healing progress is good; relying on teammates getting hit nearby is not. Reactive Healing is a nice tempo bonus when chaos happens naturally.","publicationStatus":"published","tags":["Passive Recovery","Solo Q"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Ada Wong"},"synergyPerkIds":["resurgence","botany-knowledge","self-care"],"synergyOther":["Med-Kits"],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Resurgence","Botany Knowledge","Self-Care","Med-Kits"],"antiSynergies":[],"name":"Reactive Healing","alternateName":null,"source":"Ada Wong","status":"Live 10.2.0","currentEffect":"Whenever another Survivor within 32 metres loses a Health State by any means while you are in the Injured State, grants you 40/45/50% of your missing Healing Progress toward your Health Bar. Repeated triggers can provide additional progress; the effect rounds up to full health when only a tiny amount of healing is missing.","activation":["Be in the Injured State when another Survivor within 32 metres loses a Health State by any means.","Ends/deactivates when: The instant Healing Progress grant occurs on each qualifying event; no separate timed effect is stated."],"patchNote":"Latest live balance change (7.1.1): Added rounding up to 100% healing when only a tiny amount of Healing Progress is missing.","plainEnglishSummary":"A nearby teammate losing a Health State gives you part of the Healing Progress you still need while you are injured.","cooldown":null,"duration":[],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["The 7.1.1 live update changed rounding so a trigger that leaves only a tiny amount of healing missing completes the Health State."],"sourceCharacter":"Ada Wong","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"teamwork-power-of-two","rank":126,"tier":"C","roles":["Mobility","Healing","Team Support"],"summary":"After you finish healing another Survivor, both of you gain 5% Haste while remaining within up to 16 metres of each other.","metaStatus":"Situational","skillLevel":"Medium–High","soloQ":1,"swf":3,"unlockPriority":"Medium","glossaryKeys":["haste","swf","health-state"],"useCases":["Create a two-Survivor Haste pair after a heal.","Use the speed to coordinate bodyblocks, paired rotations, or chase support.","Pair with Blood Pact-style tether builds for unusual movement advantages."],"counters":["The effect requires staying near the healed Survivor.","Splitting up for efficient generator pressure ends the Haste after the short linger.","Only one instance can affect a Survivor at once."],"pros":["Five percent Haste is meaningful.","Applies to both players.","No fixed duration while the tether is maintained."],"cons":["Tether conflicts with normal split pressure.","Requires completing a heal first.","Awkward in Solo Q."],"analysis":["Teamwork: Power of Two ranks here because 5% Haste is strong enough to affect real chase geometry, but the tether condition fights Survivor macro. The two players must remain within sixteen metres of each other to preserve the effect beyond its brief linger.","In coordinated play, that can be exploited deliberately. One Survivor can support a chase, bodyblock, or rotate alongside the other while both move faster. The same idea is much harder to sustain with a random teammate who may immediately run in another direction.","The heal trigger is reasonable and occurs naturally, but the best play after a heal is often for the two Survivors to split up and pressure different objectives. Power of Two rewards the opposite behavior.","That tension keeps the perk from climbing higher. Its movement bonus is absolutely real; the cost is organizing the team around a pair when the game often rewards four independent pressure points."],"verdict":"Five percent Haste for two Survivors is powerful, but the leash is the perk. Power of Two shines in coordinated pair play and fades quickly when efficient macro requires you to split.","publicationStatus":"published","tags":["Haste","Teamwork"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Thalita Lyra"},"synergyPerkIds":["blood-pact","empathic-connection","botany-knowledge","teamwork-collective-stealth"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Blood Pact","Empathic Connection","Botany Knowledge","Teamwork: Collective Stealth"],"antiSynergies":[],"name":"Teamwork: Power of Two","alternateName":null,"source":"Thalita Lyra","status":"Live 10.2.0","currentEffect":"Whenever you finish healing another Survivor, you and the healed Survivor gain 5% Haste while within 8/12/16 m of one another. The effect lingers for 4 seconds after leaving range and resumes if you re-enter range before the linger ends. Survivors can only be affected by one instance of Teamwork: Power of Two at a time.","activation":["Finish healing another Survivor.","Both Survivors must remain within 8/12/16 m to keep Haste active.","Ends/deactivates when: Haste ends 4 seconds after leaving range unless you re-enter before the timer ends."],"patchNote":"Latest live balance change (8.3.0): Removed the cooldown and the health-state loss cancellation; clarified that the effect does not stack.","plainEnglishSummary":"Finishing a heal gives you and that teammate Haste while you stay close together.","cooldown":null,"duration":["Continues while within range; lingers for 4 seconds after leaving range."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":"A Survivor can be affected by only one instance of this perk at a time.","statusEffectsInvolved":["Haste"],"specialInteractions":["The effect applies to both the healer and the healed Survivor; it does not stack with another instance of this perk."],"sourceCharacter":"Thalita Lyra","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"invocation-weaving-spiders","rank":127,"tier":"C","roles":["Objective","Invocation","Information"],"summary":"Complete a 60-second Basement Invocation to permanently reduce every remaining generator's required charges by up to 10, then become Injured and Broken for the rest of the Trial.","metaStatus":"Situational","skillLevel":"Medium–High","soloQ":1,"swf":3,"unlockPriority":"Medium","glossaryKeys":["broken","pressure","swf"],"useCases":["Front-load a global objective reduction when several generators remain unfinished.","Coordinate teammates to accelerate the Invocation when the team has deliberately built around it.","Create permanent objective progress that cannot be removed by ordinary regression."],"counters":["The invoker spends substantial time traveling to and performing in the Basement.","Completion leaves the invoker Broken for the rest of the Trial.","Poor timing can trade more Survivor tempo for the ritual than the generator reduction returns."],"pros":["Global permanent effect on every remaining generator.","Can be accelerated by teammates.","Ordinary regression cannot restore the removed maximum requirement."],"cons":["Large setup and travel cost.","Permanent Broken penalty.","Can encourage multiple Survivors to abandon generators for the ritual."],"analysis":["Invocation: Weaving Spiders ranks in the middle of this band because its reward is genuinely global. Completing the ritual reduces the maximum repair requirement of every remaining generator, creating permanent progress that does not behave like a normal repair bar the Killer can simply kick away.","The arithmetic is not automatically favorable. The invoker spends travel time plus as much as sixty seconds in the Basement, and helpers accelerate the ritual by sacrificing their own objective time. The team must receive enough value from the reduced generator requirements to repay that investment.","The permanent Broken penalty is also significant. The invoker becomes easier to down for the rest of the Trial and loses normal healing options, so the perk effectively converts personal safety into team objective pressure.","Coordinated teams can plan around that trade and finish the ritual early while many generators remain. In Solo Q, the same play can look like someone disappearing into the Basement while the team needs immediate help. The ceiling is real; the consistency is not."],"verdict":"A global objective investment with a permanent personal price. Weaving Spiders can create meaningful team progress, but sixty Basement seconds and permanent Broken make the decision far from free.","publicationStatus":"published","tags":["Global"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Sable Ward"},"synergyPerkIds":["no-mither","resilience","deja-vu","invocation-treacherous-crows"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["No Mither","Resilience","Déjà Vu","Invocation: Treacherous Crows"],"antiSynergies":[],"name":"Invocation: Weaving Spiders","alternateName":null,"source":"Sable Ward","status":"Live 10.2.0","currentEffect":"While in the Basement near the Invocation circle, press Activate Ability 2 to begin a 60-second ritual. Your Aura is revealed to all other Survivors during it. Other Survivors can join; each joining Survivor increases ritual speed by 100% if they have an Invocation perk equipped, or 50% otherwise. When completed, permanently reduce the repair-charge requirement of every Generator in the Trial by 8/9/10 charges. The invoker enters the Injured State and suffers Broken for the remainder of the Trial. If everyone stops participating, unfinished ritual progress regresses; the live 8.0.0 change made full regression take 90 seconds. Completion disables other copies of this Invocation for the Trial.","activation":["Be in the Basement near the Invocation circle and press Activate Ability 2.","Complete the 60-second ritual; teammates may join to increase its speed.","Ends/deactivates when: If no Survivor continues the ritual, its progress regresses back to zero.","Ends/deactivates when: The Broken Status Effect on the invoker lasts for the remainder of the Trial."],"patchNote":"Latest live balance change (8.0.0): Reduced ritual completion time from 120 to 60 seconds and slowed full regression of interrupted progress from 6 to 90 seconds.","plainEnglishSummary":"A Basement ritual permanently lowers every Generator's repair requirement, while leaving the invoker Injured and Broken for the Trial.","cooldown":null,"duration":["Ritual: 60 seconds before helper speed modifiers.","Interrupted ritual progress takes 90 seconds to fully regress under the live regression rule.","Generator repair requirement reduction and Broken: permanent for the remainder of the Trial."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":"This Invocation can be completed once per Trial across all Survivors; completion disables other copies of Invocation: Weaving Spiders.","statusEffectsInvolved":["Broken"],"specialInteractions":["During an Invocation, teammates can join and speed it up; those with any Invocation perk contribute +100% speed, while those without contribute +50%."],"sourceCharacter":"Sable Ward","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"lucky-star","rank":128,"tier":"C","roles":["Stealth","Locker","Information"],"summary":"While in a Locker, suppress pain sounds; after exiting, spend 30 seconds suppressing pain sounds and Blood while seeing every teammate and the nearest generator.","metaStatus":"Situational","skillLevel":"Low–Medium","soloQ":3,"swf":2,"unlockPriority":"Medium","glossaryKeys":["aura-reading","reset"],"useCases":["Use a Locker to create a quiet thirty-second injured rotation.","Exit with full teammate information to choose a heal, rescue, or safer route.","Use the nearest generator Aura to rejoin productive play after hiding."],"counters":["Requires entering a Locker to begin the post-exit package.","Scratch Marks are not suppressed by the perk.","Locker detours can waste more time than the information saves."],"pros":["Thirty-second duration is generous.","Combines stealth and useful team/objective information.","Short Tier III cooldown allows repeated use."],"cons":["Locker setup tax.","Does not hide Scratch Marks.","Can encourage unnecessary hiding."],"analysis":["Lucky Star ranks around the B/C boundary because its thirty-second post-Locker package is broader than it first appears. Pain sounds and Pools of Blood disappear, every teammate becomes visible, and the nearest generator is highlighted at the same time.","That makes the perk more useful for rotations than for hiding in the Locker itself. An injured Survivor can emerge with enough information to choose whether to seek a heal, take a rescue route, or return to the nearest objective while leaving fewer tracking cues.","The setup remains a real cost. Running to a Locker simply to activate Lucky Star can waste more time than the perk returns, and Scratch Marks still reveal a sprinting route unless another effect covers them.","It is therefore best in builds already using Lockers for Head On, Inner Strength, Flashbang crafting, or Quick & Quiet. In those contexts the activation cost becomes much smaller."],"verdict":"A surprisingly broad post-Locker utility package. Lucky Star is good when the Locker was already part of your plan and inefficient when you detour solely to turn it on.","publicationStatus":"published","tags":[],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Ellen Ripley"},"synergyPerkIds":["quick-quiet","head-on","inner-strength","deception"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Quick & Quiet","Head On","Inner Strength","Deception"],"antiSynergies":[],"name":"Lucky Star","alternateName":null,"source":"Ellen Ripley","status":"Live 10.2.0","currentEffect":"While hiding inside a Locker, suppresses your Grunts of Pain for as long as you remain inside. After exiting the Locker, for 30 seconds it suppresses your Grunts of Pain and creation of Pools of Blood, reveals all other Survivors' Auras to you, and reveals the nearest Generator's Aura to you in yellow. It then has a 35/30/25-second cooldown.","activation":["Hide inside a Locker.","Ends/deactivates when: The inside-Locker effect ends when you exit.","Ends/deactivates when: The post-exit effects end after 30 seconds; cooldown prevents reactivation."],"patchNote":"Latest live balance change (9.2.0): Reduced cooldown from 40/35/30 to 35/30/25 seconds.","plainEnglishSummary":"Hiding in a Locker silences your pain sounds, and exiting gives 30 seconds of stealth and Aura information before cooldown.","cooldown":"35/30/25 seconds after the post-exit effect (Tier I/II/III).","duration":["While in Locker: suppresses Grunts of Pain for the time you remain inside.","After exiting: suppression and Aura effects last 30 seconds."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["After exiting, the perk reveals every other Survivor and the nearest Generator; the Generator Aura is yellow."],"sourceCharacter":"Ellen Ripley","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"urban-evasion","rank":129,"tier":"C","roles":["Stealth","Mobility"],"summary":"Move at normal walking speed while crouched at Tier III.","metaStatus":"Situational","skillLevel":"Low","soloQ":3,"swf":2,"unlockPriority":"Medium","glossaryKeys":["pressure"],"useCases":["Reposition around low cover without standing and exposing your model.","Move quickly while avoiding some Killer sightlines and powers that care about posture.","Navigate stealth-heavy indoor or edge-map situations with less crouch-speed penalty."],"counters":["Crouching is still slower than running.","Overusing the perk can destroy map tempo.","Many Killers can detect or pressure crouched Survivors normally."],"pros":["Permanent and simple.","Removes the normal movement tax from crouching relative to walking.","Useful around low obstacles and stealth situations."],"cons":["Easy to misuse by crouching unnecessarily.","No chase burst or action-speed benefit.","Often weaker than simply learning when to run."],"analysis":["Urban Evasion ranks this position because moving at walking speed while crouched is useful in specific geometry, but the perk has an infamous trap: it can make inefficient movement feel safe. The effect is strongest when crouching is already the correct tactical choice.","Low-cover tiles and certain Killer interactions can reward staying crouched while repositioning. In those moments, doubling crouch movement speed makes the posture much less costly.","The problem is players treating crouching as a default travel mode. Even fast crouching is dramatically slower than sprinting across the map, and map pressure is often more important than avoiding a hypothetical detection event.","Urban Evasion is therefore a decent utility perk with a behavior tax. Used deliberately it has a niche; used constantly it can make the player less effective than if they had equipped nothing."],"verdict":"A situational movement tool, not permission to crouch everywhere. Urban Evasion is good when posture matters and bad when it replaces normal rotation speed.","publicationStatus":"published","tags":["Crouch"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Nea Karlsson"},"synergyPerkIds":["fixated","still-sight","boon-shadow-step","light-footed"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Fixated","Still Sight","Boon: Shadow Step","Light-Footed"],"antiSynergies":[],"name":"Urban Evasion","alternateName":null,"source":"Nea Karlsson","status":"Live 10.2.0","currentEffect":"Permanently increases your Movement speed while crouched by 90/95/100%.","activation":["Be moving while crouched.","Ends/deactivates when: The bonus applies only while crouched."],"patchNote":"Latest live balance change (1.7.0): Removed the uninjured requirement and increased crouched movement speed bonus to 90/95/100%.","plainEnglishSummary":"Lets you move faster while crouching.","cooldown":null,"duration":[],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":[],"sourceCharacter":"Nea Karlsson","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"a-place-for-us","rank":130,"tier":"C","roles":["Healing","Stealth"],"summary":"While healing another Survivor, both of you gain Elusive; completing a heal on the Obsession extends Elusive for up to 30 seconds.","metaStatus":"Situational","skillLevel":"Low–Medium","soloQ":2,"swf":2,"unlockPriority":"Medium","glossaryKeys":["aura-reading","reset","health-state"],"useCases":["Protect both healer and patient from Aura reads and trail tracking during a reset.","Create a long post-heal stealth window when the target is the Obsession.","Use safe healing zones to rotate both Survivors without leaving normal tracking cues."],"counters":["Requires healing another Survivor.","The long timed extension only occurs when you fully heal the Obsession.","Direct sight and non-covered tracking can still reveal you."],"pros":["Protects two Survivors at once during healing.","Thirty-second Obsession extension can cover a full rotation.","Strong information-denial theme."],"cons":["Target-dependent ceiling.","No healing-speed bonus.","Does nothing when you are the one receiving the heal."],"analysis":["A Place for Us ranks this position because Elusive is a broad stealth package, and applying it to both healer and patient can make a reset safer against Aura-heavy Killers. The base effect is present whenever you heal another Survivor rather than requiring a cooldown or token.","The Obsession clause raises the ceiling substantially. Completing that heal can extend Elusive to both Survivors for up to thirty seconds, enough time to leave the area and reposition without normal Aura, Scratch-Mark, Blood, or pain-sound tracking.","The weakness is that the perk does not make the heal itself faster. If the Killer simply walks back before the interaction finishes, information denial may not compensate for the time spent resetting.","It sits in B because the protection is useful but target-dependent. Against heavy tracking builds or when the Obsession needs repeated heals, it can perform far above this slot."],"verdict":"A solid two-person stealth shield during resets. A Place for Us is strongest when the Obsession clause turns one completed heal into a long protected rotation.","publicationStatus":"published","tags":["Information Denial"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Kwon Tae-Young"},"synergyPerkIds":["empathic-connection","botany-knowledge","bound-by-obsession","boon-shadow-step"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Empathic Connection","Botany Knowledge","Bound by Obsession","Boon: Shadow Step"],"antiSynergies":[],"name":"A Place for Us","alternateName":null,"source":"Kwon Tae-Young","status":"Live 10.2.0","currentEffect":"While healing another Survivor, you and that Survivor gain Elusive. If you complete healing the Obsession, both of you gain Elusive for 20/25/30 seconds. At Trial start, the perk reduces your chance of becoming the initial Obsession.","activation":["Begin healing another Survivor.","Complete healing the Obsession for the tiered timed effect.","The initial-Obsession chance modifier applies at Trial start.","Ends/deactivates when: The in-progress effect ends when the heal ends; the completed-heal effect ends after its timer."],"patchNote":"Latest live balance change (9.5.0): Introduced the perk with Elusive sharing during a heal and a 20/25/30-second effect after completing a heal on the Obsession.","plainEnglishSummary":"Healing a teammate grants both of you Elusive, with a timed extension after healing the Obsession; the perk also reduces your chance to become the initial Obsession.","cooldown":null,"duration":["Elusive during the heal; 20/25/30 seconds after completing a heal on the Obsession."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":["Elusive"],"specialInteractions":["At Trial start, you are less likely to become the Obsession."],"sourceCharacter":"Kwon Tae-Young","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"clean-break","rank":131,"tier":"C","roles":["Healing","Self-Sustain"],"summary":"After healing another Survivor, you can interrupt a heal on yourself to become Broken and automatically heal one Health State after 45 seconds if you avoid the Dying State.","metaStatus":"Situational","skillLevel":"Medium","soloQ":2,"swf":3,"unlockPriority":"Medium","glossaryKeys":["broken","health-state","reset"],"useCases":["Release a teammate from finishing your heal and let them return to objectives.","Bank a delayed autonomous heal after first helping another Survivor.","Stay productive during the delay instead of occupying a teammate for the full reset."],"counters":["You must first finish healing another Survivor and then begin receiving a heal yourself.","You are Broken during the delay.","Entering the Dying State cancels the effect."],"pros":["Can free the healer to leave early.","10.1 reduced the Tier III delay to 45 seconds.","Automatic health-state recovery requires no teammate at completion."],"cons":["Multiple setup steps.","Forty-five seconds is still a long vulnerable window.","A tunnel or ordinary down cancels the payoff."],"analysis":["Clean Break ranks here because the 10.1 reduction to forty-five seconds made the delayed heal more practical, but the perk still asks for a surprisingly elaborate sequence. You must heal someone first, start receiving a heal, then deliberately convert that interaction into Broken and wait.","The intended tempo benefit is that your teammate can leave rather than spending the full healing interaction on you. During the delay you can repair, rotate, or perform another useful action while the automatic health state approaches.","The risk is obvious: forty-five seconds is plenty of time for the Killer to find and down an injured Survivor. Going Dying cancels the payoff entirely, so the perk is weakest in the exact high-pressure situations where a delayed heal sounds most attractive.","Clean Break is therefore legitimate but conditional self-sustain. The buff helped, yet simpler perks still create healthier and faster resets with less ceremony."],"verdict":"A workable delayed heal after its 10.1 buff, but still a multi-step promise that the Killer can cancel with one down. Useful when you can stay productive and safe for the full timer.","publicationStatus":"published","tags":["Delayed Heal"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Taurie Cain"},"synergyPerkIds":["resilience","dead-hard","made-for-this","empathic-connection"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Resilience","Dead Hard","Made for This","Empathic Connection"],"antiSynergies":[],"name":"Clean Break","alternateName":null,"source":"Taurie Cain","status":"Live 10.2.0","currentEffect":"After you finish healing another Survivor, Clean Break activates. While another Survivor heals you, use the Active Ability button to become Broken; if you are not in the Dying State, you automatically heal one Health State after 75/60/45 seconds. Becoming Dying cancels the effect. It cannot activate while you are already Broken.","activation":["Complete a healing action on another Survivor.","While another Survivor heals you, use the Active Ability button.","You must not already be Broken.","Ends/deactivates when: Entering the Dying State cancels the delayed heal.","Ends/deactivates when: The effect ends after healing one Health State."],"patchNote":"Latest live balance change (10.1.0): Changed the delay to 75/60/45 seconds.","plainEnglishSummary":"After healing someone, you can become Broken during a heal from another teammate and automatically heal later if you stay out of the Dying State.","cooldown":null,"duration":["Delayed self-heal: 75/60/45 seconds by tier."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":["Broken"],"specialInteractions":["The perk requires another Survivor to heal you to activate the delayed-heal effect."],"sourceCharacter":"Taurie Cain","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"scene-partner","rank":132,"tier":"C","roles":["Information","Chase"],"summary":"While inside the Terror Radius, looking at the Killer makes you scream and reveal their Aura for up to 6 seconds, with a 50% chance for a second scream and 2 extra seconds.","metaStatus":"Situational","skillLevel":"Medium","soloQ":3,"swf":2,"unlockPriority":"Medium","glossaryKeys":["aura-reading","terror-radius","looping"],"useCases":["Force a Killer Aura read through walls when you know they are nearby.","Use the information at tall loops or indoor structures to remove a mindgame.","Pair with scream-related synergies or Eyes of Belmont for longer reads."],"counters":["The scream reveals your position audibly.","Forty-second cooldown.","Requires being in the Terror Radius and looking toward the Killer."],"pros":["Player-controlled information trigger.","Potential eight-second Killer Aura read.","Useful at structures where visual contact is normally poor."],"cons":["Announces your location with a scream.","Long cooldown.","Stealth Killers can deny Terror Radius access."],"analysis":["Scene Partner takes this position because its downside and upside are tied together. Looking at the Killer inside the Terror Radius deliberately makes you scream, but in exchange you receive a meaningful Aura read that can last even longer if the second scream triggers.","At a tall loop, the information can be worth the noise. Once the Killer already knows roughly where you are, revealing their precise side of the structure can remove the guess that would otherwise decide the chase.","The perk is worse as stealth information because the scream itself gives the Killer a cue. It also struggles against Undetectable Killers who may not provide the Terror Radius condition at all.","Scene Partner is therefore a fun, functional chase-information perk. It is best when you accept that subtlety has already left the building."],"verdict":"A loud but legitimate information tool. Scene Partner trades stealth for wallhacks, which is often reasonable once the Killer already knows where you are.","publicationStatus":"published","tags":["Aura Reading"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Nicolas Cage"},"synergyPerkIds":["eyes-of-belmont","troubleshooter","quick-quiet","still-sight"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Eyes of Belmont","Troubleshooter","Quick & Quiet","Still Sight"],"antiSynergies":[],"name":"Scene Partner","alternateName":null,"source":"Nicolas Cage","status":"Live 10.2.0","currentEffect":"While inside the Killer's Terror Radius, looking at the Killer makes you scream and reveals the Killer's Aura for 4/5/6 seconds. There is a 50% chance you scream a second time, extending the Aura reveal by 2 seconds. Cooldown: 40 seconds.","activation":["Be inside the Killer's Terror Radius and look at the Killer.","Ends/deactivates when: Aura reveal ends after its duration."],"patchNote":"Latest live balance change (8.4.0): Increased Killer Aura reveal to 4/5/6 seconds and reduced cooldown to 40 seconds.","plainEnglishSummary":"Looking at the Killer from within their Terror Radius makes you scream and briefly reveals their Aura, with a chance to extend the reveal.","cooldown":"40 seconds","duration":["Killer Aura reveal: 4/5/6 seconds, with a possible additional 2 seconds after the second scream."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["The second scream has a 50% chance to occur and adds 2 seconds to the Aura reveal."],"sourceCharacter":"Nicolas Cage","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"down-to-the-last","rank":133,"tier":"C","roles":["Endgame","Team Support"],"summary":"Build Tokens from hooks and Generator completions to speed teammates’ Exit Gates; with 3+ Tokens as last Survivor, unlock Hatch and block Killer Aura reading.","metaStatus":"Situational","skillLevel":"Low","soloQ":2,"swf":3,"unlockPriority":"Low–Medium","glossaryKeys":["aura-reading","hook-state"],"useCases":["Accumulate Tokens naturally through Generator completions and your own hooks.","Give teammates faster Exit Gate opening in endgame.","Use the last-Survivor Hatch unlock and Aura denial as a fallback if the team collapses."],"counters":["Most value is delayed until endgame.","Hatch unlock matters only when you are the last Survivor and have at least three Tokens.","A perk that plans for being alone may contribute little to preventing that outcome."],"pros":["Team gate speed scales up to six Tokens.","Token generation comes from normal match events.","Last-Survivor clause can unlock a closed Hatch."],"cons":["Back-loaded.","Part of the kit assumes the team is dead.","No direct chase or midgame repair bonus."],"analysis":["Down to the Last was completely reworked in 10.2. The old “other Survivors die, you get stronger” structure was replaced with Tokens earned from your own hooks and Generator completions.","Each Token speeds other Survivors’ Exit Gate opening by 10%, giving the perk an actual team-facing endgame purpose instead of pure selfish survival. At high Token counts, that can be a large bonus.","If you do become the last Survivor with at least three Tokens, the perk adds a Hatch-unlock option and temporary Aura protection from the Killer, preserving a comeback identity without making it the whole perk.","The rework is healthier but still heavily back-loaded. It should be judged as an endgame team utility perk with a last-person fallback, not as a general match-impact perk."],"verdict":"A healthier 10.2 redesign with team gate value before the selfish fallback. Still endgame-heavy, but no longer waits for everyone else to die before doing anything useful.","publicationStatus":"published","reviewFlags":["10.2-live-change","v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"tags":["Team","Last Survivor"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"general","sourceCharacter":"General"},"synergyPerkIds":["wake-up","no-one-left-behind","hope","left-behind"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"synergies":["Wake Up!","No One Left Behind","Hope","Left Behind"],"antiSynergies":[],"name":"Down to the Last","alternateName":null,"source":"General perk","status":"Live 10.2.0","currentEffect":"Whenever you are hooked or complete a Generator, gain 1 Token, up to 6. For each Token, other Survivors open Exit Gates 10% faster. When you are the last Survivor alive and have at least 3 Tokens, you can unlock the Hatch and, for each Token, the Killer cannot see your Aura for 6/8/10 seconds.","activation":["Be hooked or complete a Generator to gain 1 Token, up to 6.","Other Survivors receive the Exit Gate speed benefit for each Token you hold.","To unlock the Hatch and receive Aura protection, be the last Survivor alive with at least 3 Tokens.","Ends/deactivates when: The last-Survivor Aura protection expires after 6/8/10 seconds per Token."],"patchNote":"Latest live balance change (10.2.0): Complete rework: Tokens now come from being hooked or completing Generators, speed other Survivors' Exit Gate opening, and enable Hatch unlocking plus Aura-reading protection for the last Survivor.","plainEnglishSummary":"Hooks and Generator completions build up to six tokens that speed teammates' Exit Gate opening and, if you become the last Survivor, can unlock the Hatch and block Killer Aura reading.","cooldown":null,"duration":["Last-Survivor Aura protection: 6/8/10 seconds per Token."],"tokenOrStackBehavior":"Gain 1 Token when hooked or when you complete a Generator, up to 6. Each Token grants other Survivors +10% Exit Gate-opening speed and, when you are the last Survivor with at least 3 Tokens, contributes 6/8/10 seconds of Aura protection.","oncePerTrialOrOtherLimits":"Maximum 6 Tokens; Hatch unlocking requires being the last Survivor with at least 3 Tokens.","statusEffectsInvolved":[],"specialInteractions":["The Hatch-unlock ability is available only while you are the last Survivor and have at least 3 Tokens."],"sourceCharacter":"General","isGeneralPerk":true,"currentLivePatchVerified":"10.2.0"},{"id":"light-footed","rank":134,"tier":"C","roles":["Stealth","Chase"],"summary":"While Healthy and off cooldown, your running footsteps are silent; a Rushed Vault disables the effect for 10 seconds at Tier III.","metaStatus":"Situational","skillLevel":"Low–Medium","soloQ":3,"swf":2,"unlockPriority":"Medium","glossaryKeys":["looping","health-state"],"useCases":["Make line-of-sight breaks harder to solve through footstep audio.","Approach or leave areas while Healthy without broadcasting normal running sounds.","Pair sound denial with hidden Scratch Marks or quiet pain sounds for stronger stealth."],"counters":["Becoming Injured ends the active effect.","Rushed Vaults disable it temporarily.","Visual tracking and other sound cues still exist."],"pros":["Passive while Healthy.","Removes a real Killer tracking cue.","No activation button."],"cons":["Health-state dependent.","Rushed-vault cooldown is awkward in chase.","Footsteps are only one information channel."],"analysis":["Light-Footed ranks this position because footstep audio matters more than perk descriptions usually communicate. Good Killers use running sounds to track Survivors around walls, especially when Scratch Marks are messy or visual contact is broken.","Silencing those footsteps while Healthy can create genuine uncertainty. The effect is strongest in indoor maps and dense structures where the Killer often hears a Survivor before seeing them.","The conditions keep it modest. Injury turns the value off, and a Rushed Vault starts a ten-second cooldown at Tier III, which means the perk is least reliable during exactly the kind of frantic chase sequence where silent movement sounds most attractive.","Light-Footed therefore works best as one layer in a broader stealth package. Alone, it is useful but too narrow for a higher ranking."],"verdict":"A subtle sound-denial perk that good stealth players can exploit. Light-Footed matters around walls, but its Healthy requirement and vault cooldown limit the ceiling.","publicationStatus":"published","tags":["Sound Denial"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Ellen Ripley"},"synergyPerkIds":["lightweight","boon-shadow-step","quick-quiet","iron-will"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Lightweight","Boon: Shadow Step","Quick & Quiet","Iron Will"],"antiSynergies":[],"name":"Light-Footed","alternateName":null,"source":"Ellen Ripley","status":"Live 10.2.0","currentEffect":"While Healthy, suppresses the sound of your footsteps while running. After you perform a Rushed Vault, the perk has a 14/12/10-second cooldown.","activation":["Be Healthy.","Not be in the cooldown following a Rushed Vault.","Ends/deactivates when: Becoming Injured ends the effect; performing a Rushed Vault starts the tier-specific cooldown."],"patchNote":"Latest live balance change (9.0.0): Reduced cooldown after a Rushed Vault from 28/24/20 to 14/12/10 seconds.","plainEnglishSummary":"While Healthy and off cooldown, it silences your running footsteps.","cooldown":"14/12/10 seconds after a Rushed Vault (Tier I/II/III).","duration":["No fixed active duration; effect applies while Healthy and off cooldown."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":[],"sourceCharacter":"Ellen Ripley","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"teamwork-full-circuit","rank":135,"tier":"C","roles":["Objective","Team Support","Skill Check"],"summary":"While repairing with at least one teammate, repair 5% faster and enlarge Good Skill Check zones by up to 25% for each other Survivor present.","metaStatus":"Situational","skillLevel":"Low","soloQ":2,"swf":3,"unlockPriority":"Medium","glossaryKeys":["pressure","swf"],"useCases":["Gain a small cooperative repair bonus on generators the team deliberately stacks.","Make Good Skill Checks easier for newer teammates or difficult Skill Check situations.","Pair with other co-op repair perks in coordinated objective builds."],"counters":["Provides no repair bonus while working alone.","Five percent does not erase the strategic cost of unnecessary generator stacking.","Larger Good Skill Check zones provide little value to players already hitting Greats consistently."],"pros":["Simple passive co-op repair bonus.","Can help less experienced players avoid misses.","No cooldown or token system."],"cons":["Zero solo value.","Skill Check enlargement can actually be undesirable in Great-focused builds.","Outclassed by stronger cooperative repair options."],"analysis":["Teamwork: Full Circuit sits near the tier boundary because a permanent 5% repair bonus while cooperating is useful, but not transformative. The perk only exists while another Survivor is on the same generator, and Survivors often create more map pressure by repairing separately.","The enlarged Good Skill Check zone is primarily accessibility rather than high-level power. Newer players may appreciate the safer checks, while Hyperfocus users and confident Great-check players receive almost no benefit from that half.","Friendly Competition ranks higher because its 10% reward can follow the participating Survivors onto later generators after they split. Full Circuit requires continued co-op repair to keep paying.","It remains a functional objective perk, especially in SWF builds intentionally designed around shared generators. As a general queue choice, the slot has too little value whenever you are working alone."],"verdict":"A straightforward co-op repair perk with a low ceiling. Full Circuit helps when you were already going to stack the generator, but should not be the reason you stack it.","publicationStatus":"published","tags":["Co-op"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Dustin Henderson"},"synergyPerkIds":["prove-thyself","friendly-competition","better-together","teamwork-soft-spoken"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Prove Thyself","Friendly Competition","Better Together","Teamwork: Soft-Spoken"],"antiSynergies":[],"name":"Teamwork: Full Circuit","alternateName":null,"source":"Dustin Henderson","status":"Live 10.2.0","currentEffect":"For each other Survivor repairing a Generator with you, the Good Skill Check zone increases by 15/20/25%. While repairing with at least one other Survivor, you repair 5% faster.","activation":["Repair a Generator with at least one other Survivor for the 5% repair-speed bonus.","Each additional Survivor repairing with you increases the Good Skill Check zone.","Ends/deactivates when: Bonuses end when you stop repairing with the other Survivor or Survivors."],"patchNote":"Latest live balance change (9.4.0): Introduced; no later material live balance change located in the official notes checked.","plainEnglishSummary":"Cooperative repairs are faster and have a larger Good Skill Check zone for each teammate on the Generator.","cooldown":null,"duration":[],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["The skill-check zone increase is per other Survivor repairing that Generator with you."],"sourceCharacter":"Dustin Henderson","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"repressed-alliance","rank":136,"tier":"C","roles":["Objective"],"summary":"After enough repair time, block a generator you are repairing alone for 15 seconds, preventing anyone from interacting with it during the block.","metaStatus":"Situational","skillLevel":"High","soloQ":2,"swf":3,"unlockPriority":"Medium","glossaryKeys":["pressure"],"useCases":["Protect stored generator progress from an imminent Killer kick or regression interaction.","Freeze a dangerous generator while the team handles immediate pressure elsewhere.","Use the white Aura to communicate the protected generator to teammates."],"counters":["The Entity block also prevents Survivors from repairing the generator.","Activation requires prior repair time and solo interaction.","Poor timing can protect the generator from your own team more than from the Killer."],"pros":["Player-controlled anti-regression window.","Can deny a Killer's intended generator interaction.","Useful communication Aura."],"cons":["Only fifteen seconds.","High timing requirement.","Can actively hurt the team when misused."],"analysis":["Repressed Alliance ranks here because generator blocking is one of the rare Survivor effects that can directly deny the Killer access to an objective interaction. If a Killer arrives intending to kick a highly progressed generator, a well-timed block can preserve that progress through the immediate pressure window.","The same block also locks Survivors out, which is why the perk demands judgment. Fifteen seconds can be perfect when everyone needs to flee, or disastrous when a teammate was about to finish the generator.","Activation requires enough prior repair time and only works while repairing alone, so it is not an emergency button available from the start of the match. The user has to prepare the tool before the relevant regression threat appears.","That makes Repressed Alliance a specialist B/C perk for players who understand generator timing. The effect is genuinely unique, but mistakes are unusually capable of helping the Killer."],"verdict":"A rare Survivor-controlled generator lock. Repressed Alliance can deny regression at the perfect moment, but bad timing literally blocks your own objective.","publicationStatus":"published","tags":["Anti-Regression","Generator Control"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Cheryl Mason"},"synergyPerkIds":["wiretap","deja-vu","blast-mine","potential-energy"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Wiretap","Déjà Vu","Blast Mine","Potential Energy"],"antiSynergies":[],"name":"Repressed Alliance","alternateName":null,"source":"Cheryl Mason","status":"Live 10.2.0","currentEffect":"After repairing Generators for a total of 40/35/30 seconds, the perk activates. While repairing a Generator alone, press Active Ability to call the Entity to block the Generator you are repairing for 15 seconds. Its Aura is shown in white to all Survivors. You can trigger it only when no other Survivor is repairing that Generator; after activation the perk deactivates.","activation":["Accumulate 40/35/30 seconds of Generator repair time.","Be repairing a Generator with no other Survivor repairing it and press Active Ability.","Ends/deactivates when: The Generator remains blocked for 15 seconds.","Ends/deactivates when: The perk deactivates after activation."],"patchNote":"Latest live balance change (10.1.1): Reduced activation repair-time requirement from 55/50/45 seconds to 40/35/30 seconds.","plainEnglishSummary":"After enough total repair time, you can block the Generator you are repairing alone for 15 seconds and show its Aura to the team.","cooldown":null,"duration":["Entity block: 15 seconds."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":"Deactivates after its single activation in a Trial.","statusEffectsInvolved":[],"specialInteractions":["The blocked Generator's Aura is white to all Survivors."],"sourceCharacter":"Cheryl Mason","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"technician","rank":137,"tier":"C","roles":["Objective","Stealth","Utility"],"summary":"Generator repair noises are heard from 16 metres less far away; failed basic Skill Checks no longer explode or notify the Killer, but lose extra progress.","metaStatus":"Situational","skillLevel":"Low","soloQ":3,"swf":1,"unlockPriority":"Medium","glossaryKeys":["pressure","solo-q"],"useCases":["Repair more quietly behind walls or on indoor maps where the Killer listens for generators.","Prevent missed Skill Checks from broadcasting a Loud Noise notification.","Use as a beginner safety net while learning generator Skill Checks."],"counters":["Failed Skill Checks lose extra progress.","Experienced players should not be missing many standard generator checks.","The reduced repair-noise radius does not hide the generator's visual progress or direct line of sight."],"pros":["10.1 doubled the noise-distance reduction to 16 metres.","Completely hides the explosion notification from a miss.","Useful beginner accessibility."],"cons":["Miss penalty still hurts the objective.","Provides no speed bonus.","Value falls as Skill Check consistency and map awareness improve."],"analysis":["Technician ranks this position after its 10.1 buff because the quieter repair radius is now large enough to create real stealth value on indoor and line-of-sight-heavy maps. A Killer can pass much closer to a worked generator without receiving the normal audio cue.","The failed-check protection is beginner-friendly but should not be mistaken for efficiency. The explosion and Loud Noise notification disappear, yet the generator loses additional progress. A player who misses frequently is safer from detection while still costing the team time.","Experienced players get more value from the audio reduction than the miss protection. Finishing a risky generator behind walls can be easier when the Killer cannot hear the repair from the usual distance.","Technician remains C because it solves detection rather than repair speed and becomes less necessary with experience. It is a respectable teaching and stealth perk, not a long-term meta objective tool."],"verdict":"A much better stealth-generator perk after 10.1, but still mainly a comfort pick. Technician hides mistakes from the Killer, not from the generator's progress bar.","publicationStatus":"published","tags":["Beginner"],"queueRatingStatus":"reviewed","rankRange":[130,150],"rankConfidence":"Low","rankStatus":"stable","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Feng Min"},"synergyPerkIds":["deja-vu","hyperfocus","lightweight"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","rank-review-applied","queue-rating:audit-partial-plus-normalized"],"synergies":["Déjà Vu","Hyperfocus","Lightweight"],"antiSynergies":[],"name":"Technician","alternateName":null,"source":"Feng Min","status":"Live 10.2.0","currentEffect":"While repairing a Generator, reduces the audible range of all repair-related noises by 16 m. A failed Skill Check causes the Generator to lose 4/3/2% additional progress, but suppresses the Generator explosion and Loud Noise Notification normally triggered by that failed check.","activation":["Be repairing a Generator; the quieter-noise effect applies during repair.","Fail a Skill Check to suppress the explosion and notification while incurring the tiered extra progress loss.","Ends/deactivates when: The effects apply only while repairing a Generator."],"patchNote":"Latest live balance change (10.1.0): Reduced repair noise range by 16 m instead of 8 m and reduced extra missed-check progress loss to 4/3/2% from 5/4/3%.","plainEnglishSummary":"Makes Generator repair quieter and hides failed Skill Check alerts, but increases the progress lost when a check is missed.","cooldown":null,"duration":[],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["A failed Skill Check still loses extra Generator progress even though its explosion and Loud Noise Notification are suppressed."],"sourceCharacter":"Feng Min","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"scavenger","rank":138,"tier":"C","roles":["Item","Objective","Skill Check"],"summary":"With a depleted Toolbox, land five Great repair Skill Checks to fully recharge it once; the recharge applies a severe temporary repair-speed penalty, and you can also rummage once for a basic Toolbox.","metaStatus":"Situational","skillLevel":"Very High","soloQ":2,"swf":3,"unlockPriority":"Medium","glossaryKeys":["pressure"],"useCases":["Fully restore a powerful depleted Toolbox for another later burst of generator speed.","Earn the recharge while continuing normal generator work if you can hit Great Skill Checks.","Use the once-per-Trial rummage as a fallback source of a basic Toolbox."],"counters":["Requires five Great repair Skill Checks after the Toolbox is depleted.","Recharging applies a 50% repair-speed penalty for 30 seconds at Tier III.","Average players may take too long to generate five qualifying Greats."],"pros":["A full high-quality Toolbox recharge can be valuable.","Rewards strong Skill Check execution.","Includes a backup Toolbox source."],"cons":["Severe temporary repair penalty.","Long and uncertain setup.","Built to Last often provides easier Item recycling."],"analysis":["Scavenger can fully recharge a depleted Toolbox, but the route to that reward is deliberately awkward: the Toolbox must already be empty and the Survivor must then land five Great basic repair Skill Checks.","The 50% repair-speed penalty after the recharge complicates the timing of the perk's objective payoff. The user can spend that window rescuing, healing, or rotating, but doing so delays access to the refilled Toolbox.","Hyperfocus can share the same expert Great-check shell, while Built to Last offers a simpler item-recycling route. Stake Out is not support for Scavenger in live 10.2 because its special Skill Checks do not activate other Skill Check perks.","Scavenger therefore remains a high-execution resource perk with a real payoff and a much lower floor than Built to Last."],"verdict":"A full Toolbox recharge with strings attached. Scavenger can be strong in an expert Skill Check build, but five Greats plus a temporary 50% repair penalty is a steep invoice.","publicationStatus":"published","tags":["Toolbox"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Gabriel Soma"},"synergyPerkIds":["hyperfocus","built-to-last","deja-vu"],"synergyOther":[],"antiSynergyPerkIds":["stake-out"],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Hyperfocus","Built to Last","Déjà Vu"],"antiSynergies":["Stake Out"],"name":"Scavenger","alternateName":null,"source":"Gabriel Soma","status":"Live 10.2.0","currentEffect":"While holding a depleted Toolbox, each successful Great repairing Skill Check grants 1 Token, up to 5. Reaching 5 automatically consumes all 5 Tokens and fully recharges the Toolbox; this applies a 50% repair-speed penalty for 40/35/30 seconds. Once per Trial, you can rummage through an opened Chest, which guarantees a basic Toolbox.","activation":["Hold a depleted Toolbox to earn tokens from successful Great repairing Skill Checks.","Rummage through an opened Chest to use the chest effect.","Ends/deactivates when: The token-gain condition ends when no depleted Toolbox is held.","Ends/deactivates when: The repair-speed penalty ends after 40/35/30 seconds."],"patchNote":"Latest live balance change (unknown): No material live balance change could be verified from available patch history.","plainEnglishSummary":"Great repair checks recharge a depleted Toolbox after five tokens, at the cost of temporarily slower repairs, and the perk also grants one Toolbox rummage.","cooldown":null,"duration":["Repair-speed penalty: 40/35/30 seconds."],"tokenOrStackBehavior":"Earn 1 token per successful Great repairing Skill Check while holding a depleted Toolbox; cap 5. At 5, all tokens are consumed and the Toolbox is fully recharged.","oncePerTrialOrOtherLimits":"The opened-Chest rummage is once per Trial and guarantees a basic Toolbox.","statusEffectsInvolved":[],"specialInteractions":["The Toolbox recharge is automatic when the fifth token is earned."],"sourceCharacter":"Gabriel Soma","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"residual-manifest","rank":139,"tier":"C","roles":["Item","Chase","Stealth"],"summary":"Blinding the Killer inflicts Blindness for up to 30 seconds, and once per Trial you can rummage an opened Chest for a guaranteed basic Flashlight.","metaStatus":"Situational","skillLevel":"High","soloQ":2,"swf":3,"unlockPriority":"Medium","glossaryKeys":["aura-reading"],"useCases":["Turn any successful blind into a longer period where the Killer loses Aura-reading support.","Guarantee access to a basic Flashlight without bringing one into the Trial.","Use the rummage after your original Item is consumed or when a chest is already open."],"counters":["Requires successful Killer blinds to apply the main effect.","Lightborn or careful anti-blind play can shut down most value.","The guaranteed Flashlight is basic rather than premium."],"pros":["Provides its own tool for activating the perk.","Thirty seconds of Killer Blindness can disable important Aura information.","Useful in dedicated blind builds."],"cons":["High execution dependence.","Very little value if blinds are denied.","One guaranteed basic Flashlight does not justify the slot alone."],"analysis":["Residual Manifest ranks this position because it is one of the more self-contained blind-build perks. Even if you enter without a Flashlight, one rummage can guarantee a basic one, giving the perk a path to its own activation.","The Blindness effect can be meaningful against Killers relying on Aura information. Thirty seconds is long enough to cover post-hook rotations, generator pressure, or several chase decisions where the Killer expected to see an Aura.","The obvious issue is that successful blinds are not free. A Killer can face walls during pickups, avoid pallet blinds, or bring Lightborn. In those matches the main effect struggles to appear.","Residual Manifest is therefore solid specialist utility. It is better than a pure meme perk, but too dependent on blind access for a general-purpose ranking."],"verdict":"A respectable blind-build support perk that even supplies its own basic Flashlight. Strong when blinds land, nearly invisible when they do not.","publicationStatus":"published","tags":["Flashlight","Blind","Information Denial"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Haddie Kaur"},"synergyPerkIds":["champion-of-light","background-player","flashbang","built-to-last"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Champion of Light","Background Player","Flashbang","Built to Last"],"antiSynergies":[],"name":"Residual Manifest","alternateName":null,"source":"Haddie Kaur","status":"Live 10.2.0","currentEffect":"After a successful Killer Blind, the Killer suffers Blindness for 20/25/30 seconds. Once per Trial, Residual Manifest lets you rummage through an opened Chest and guarantees a Basic Flashlight.","activation":["Successfully blind the Killer to apply Blindness.","Interact with an opened Chest to use the one rummage allowed by the perk.","Ends/deactivates when: Killer Blindness ends after 20/25/30 seconds.","Ends/deactivates when: The Chest rummage allowance is spent when used."],"patchNote":"Latest live balance change (unknown): No material live balance change could be verified from available patch history.","plainEnglishSummary":"Blinding the Killer applies Blindness, and once per Trial you can rummage an opened Chest for a Basic Flashlight.","cooldown":null,"duration":["Killer Blindness: 20/25/30 seconds."],"tokenOrStackBehavior":"One rummage allowance per Trial; it is consumed when rummaging an opened Chest.","oncePerTrialOrOtherLimits":"Can rummage an opened Chest once per Trial; that rummage guarantees a Basic Flashlight.","statusEffectsInvolved":["Blindness (Killer)"],"specialInteractions":["The Killer Blindness effect can be triggered by blinds from Firecrackers, Flash Grenades, and Blast Mine.","When used with Appraisal, Residual Manifest's rummage token is consumed first."],"sourceCharacter":"Haddie Kaur","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"small-game","rank":140,"tier":"C","roles":["Totem","Information","Utility"],"summary":"Simply see the Aura of any Totem within up to 12 metres.","metaStatus":"Situational","skillLevel":"Low","soloQ":3,"swf":1,"unlockPriority":"Low","glossaryKeys":["aura-reading"],"useCases":["Find a nearby Hex without sweeping every corner manually.","Support Inner Strength, Overzealous, Counterforce, or Boon builds.","Teach newer players common Totem spawn locations."],"counters":["Twelve metres is a short detection radius.","Experienced players often know common Totem spawns already.","The perk gives no speed bonus or Killer information."],"pros":["10.2 removed the clunky cone/cooldown/token system.","Extremely easy to understand.","Works on any Totem type."],"cons":["Very narrow information category.","Low range.","Map knowledge replaces part of its value."],"analysis":["Small Game became dramatically simpler in 10.2. The directional cone, audio cue, cooldown, and narrowing-token minigame are gone; a nearby Totem simply reveals its Aura.","That is better for the actual job. If a Hex, Boon setup, or Inner Strength charge matters, the player can search naturally and receive a clear confirmation inside twelve metres.","The range is still small enough that the perk does not solve Totem locations from across the map, and experienced players will often recognize spawn patterns without it.","Small Game is therefore clean beginner and build support rather than meta information. The rework raises usability more than power."],"verdict":"Finally simple: walk near a Totem, see the Totem. Good support for Totem builds and new players, not a high-impact general slot.","publicationStatus":"published","reviewFlags":["10.2-live-change","v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"tags":["Beginner"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"general","sourceCharacter":"General"},"synergyPerkIds":["counterforce","inner-strength","overzealous"],"synergyOther":["Boon perks"],"antiSynergyPerkIds":[],"archetypeRatings":[],"synergies":["Counterforce","Inner Strength","Overzealous","Boon perks"],"antiSynergies":[],"name":"Small Game","alternateName":null,"source":"General perk","status":"Live 10.2.0","currentEffect":"Within 10/11/12 metres of a Totem, you see its Aura.","activation":["A Totem is within 10/11/12 metres.","Ends/deactivates when: The Totem's Aura is no longer revealed after it leaves the tiered range or no longer exists."],"patchNote":"Latest live balance change (10.2.0): Complete rework: now reveals a Totem's Aura within 10/11/12 metres and removes the former cone, cue, cooldown, and token mechanics.","plainEnglishSummary":"Nearby Totems reveal their Auras within a tiered radius.","cooldown":null,"duration":[],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":[],"sourceCharacter":"General","isGeneralPerk":true,"currentLivePatchVerified":"10.2.0"},{"id":"streetwise","rank":141,"tier":"C","roles":["Item","Objective"],"summary":"Items retrieved from chests gain up to 80% more charges, and the first time your held Item is depleted you see the Killer's Aura for 8 seconds.","metaStatus":"Situational","skillLevel":"Low","soloQ":2,"swf":2,"unlockPriority":"Medium","glossaryKeys":["aura-reading"],"useCases":["Turn a good chest find into a much deeper pool of Toolbox, Med-Kit, or Flashlight charges.","Combine with chest-search perks to increase the chance the bonus lands on a useful Item.","Use the depletion Aura read to understand Killer location after consuming the Item."],"counters":["The charge bonus only affects Items retrieved from chests.","Random chest loot may not be worth amplifying.","Bringing a premium Item from the lobby receives no charge bonus."],"pros":["80% extra charges is a large multiplier.","Works across multiple charged Item types.","Includes an 8-second Killer Aura read."],"cons":["Chest-dependent and loot-dependent.","Reworked version no longer supports carried lobby Items the old way.","Requires an Item to be depleted for the information payoff."],"analysis":["Streetwise ranks here because the current perk is fundamentally different from the old nearby-item-efficiency aura. It now rewards chest loot specifically, adding up to 80% more charges to charged Items found during the Trial.","That multiplier is substantial when the chest produces a useful Toolbox or Med-Kit. The problem is that the perk does not control what the chest contains, so a large bonus on an Item you did not need is still poor value.","The eight-second Killer Aura read on first depletion adds a little independent utility and can help decide what to do immediately after consuming the resource.","Streetwise therefore belongs in chest-focused builds rather than normal Item builds. Plunderer's Instinct and Appraisal can improve the loot pipeline, but the perk is too dependent on random map resources for a higher rank."],"verdict":"A huge charge multiplier attached to random chest loot. Modern Streetwise can make a great find much better, but it cannot guarantee the find is great.","publicationStatus":"published","tags":["Chest","Resource"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Nea Karlsson"},"synergyPerkIds":["plunderers-instinct","appraisal","pharmacy","built-to-last"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Plunderer's Instinct","Appraisal","Pharmacy","Built to Last"],"antiSynergies":[],"name":"Streetwise","alternateName":null,"source":"Nea Karlsson","status":"Live 10.2.0","currentEffect":"Items with Charges retrieved from Chests permanently receive 60/70/80% more Charges. The first time your currently equipped Item is depleted, the Killer's Aura is revealed to you for 8 seconds.","activation":["The increased charges apply to an Item with Charges retrieved from a Chest.","The Aura reveal triggers the first time your currently equipped Item is depleted.","Ends/deactivates when: The Killer Aura reveal ends after 8 seconds and does not repeat after its first trigger."],"patchNote":"Latest live balance change (9.1.0): Reworked the perk to give chest-found charged items 60/70/80% more Charges and reveal the Killer Aura for 8 seconds the first time the equipped Item is depleted.","plainEnglishSummary":"Chest-found charged items hold more charges, and the first time your equipped item runs out you briefly see the Killer.","cooldown":null,"duration":["Killer Aura reveal: 8 seconds."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":"The Killer Aura reveal triggers only the first time your currently equipped Item is depleted.","statusEffectsInvolved":[],"specialInteractions":["The bonus charges apply only to charge-using Items retrieved from Chests."],"sourceCharacter":"Nea Karlsson","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"boon-illumination","rank":142,"tier":"C","roles":["Boon","Information","Utility"],"summary":"Your Boon reveals nearby Chests and Generators, and while it stays lit you bless future Totems up to 200% faster.","metaStatus":"Situational","skillLevel":"Low–Medium","soloQ":2,"swf":3,"unlockPriority":"Low","glossaryKeys":["aura-reading"],"useCases":["Relocate an already-active Boon much faster when a dedicated Boon build needs to follow the active objective area.","Provide local Generator and Chest Aura information inside the Boon radius.","Support Steadfast-centered or multi-Boon packages where frequent relocation is actually part of the plan."],"counters":["The Killer can snuff the Boon and remove the active infrastructure.","The speed bonus is worded around having a lit Boon Totem; post-snuff re-blessing remains a controlled-test question.","Relocating a Boon can cost more objective time than simply staying on a Generator."],"pros":["Very large blessing-speed bonus for relocation while a Boon remains active.","Can be a strong infrastructure component in a dedicated Boon package.","Provides team-visible local objective information."],"cons":["Low global value outside a dedicated Boon build.","Does not justify moving a Boon when the relocation itself loses more time than it saves.","Post-snuff rebuild behavior should not be claimed until controlled testing settles it."],"analysis":["Boon: Illumination has a clear split between global value and archetype value. Its global rank stays low because the perk needs a meaningful Boon package before faster relocation matters.","Inside a Steadfast-centered or multi-Boon build, the relocation speed can be a real piece of infrastructure. Live gameplay showed that relocating the Boon can be extremely fast, but also showed the opportunity-cost problem: moving the Boon for modest Generator value can lose more time than simply repairing.","The current wording ties the blessing-speed bonus to already having a lit Boon Totem. The post-snuff case remains a mechanics test, so v15 does not describe fast rebuilding after a snuff as established behavior.","This is exactly why v15 separates global rank from archetype ratings: a low-global perk can still be a strong component of a specialized package."],"verdict":"Low global priority, potentially strong Boon-package infrastructure. Judge it as a specialist component, not a standalone information perk.","publicationStatus":"published","reviewFlags":["10.2-live-change","v15-schema-migrated","rank-review-applied","queue-rating:audit-explicit"],"tags":["Setup"],"queueRatingStatus":"reviewed","rankRange":[135,150],"rankConfidence":"Medium","rankStatus":"mechanics-flag","evidenceStatus":"needs-controlled-testing","acquisition":{"type":"character","sourceCharacter":"Alan Wake"},"synergyPerkIds":["boon-shadow-step","boon-circle-of-healing","boon-steadfast","boon-dark-theory"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[{"archetype":"Steadfast relocation","grade":"B+/A-","requires":["boon-steadfast"],"note":"Strong infrastructure component when an active Boon must follow generator clusters; this does not assume fast post-snuff rebuilding.","confidence":"Medium"}],"synergies":["Boon: Shadow Step","Boon: Circle of Healing","Boon: Steadfast","Boon: Dark Theory"],"antiSynergies":[],"name":"Boon: Illumination","alternateName":null,"source":"Alan Wake","status":"Live 10.2.0","currentEffect":"While next to a Totem, use the Active Ability button to bless it, creating a unique Boon Totem that combines all of your equipped Boons. Survivors within its 24-metre range see the Auras of Chests and Generators. While you have a Boon Totem, you bless Totems 150/175/200% faster.","activation":["Bless a Totem to create your Boon Totem.","Aura reading applies to Survivors within the Boon's 24-metre range.","The blessing-speed bonus requires you to have an active Boon Totem.","Ends/deactivates when: Aura reading ends outside the Boon's range or when the Boon is snuffed.","Ends/deactivates when: The blessing-speed bonus ends when you no longer have an active Boon Totem."],"patchNote":"Latest live balance change (10.2.0): Replaced the 6/8/10% Blessing/Cleansing bonus with 150/175/200% faster Blessing while the perk owner's Boon Totem is active; Aura effects remain.","plainEnglishSummary":"Your Boon reveals nearby Chests and Generators, and having an active Boon makes your future blessing actions dramatically faster.","cooldown":null,"duration":[],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":"One active Boon Totem per Survivor; all equipped Boon effects are combined on that Totem.","statusEffectsInvolved":[],"specialInteractions":["The 10.2.0 speed bonus applies to Blessing only; the former separate Blessing/Cleansing speed bonus was removed."],"sourceCharacter":"Alan Wake","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"detective-s-hunch","rank":143,"tier":"C","roles":["Information","Totem","Objective"],"summary":"Whenever a generator completes, reveal nearby generators, Totems, and chests within up to 64 metres for 20 seconds.","metaStatus":"Situational","skillLevel":"Low","soloQ":3,"swf":2,"unlockPriority":"Medium","glossaryKeys":["aura-reading","pressure"],"useCases":["Locate Totems after generator completions without searching blindly.","Plan the next generator rotation using a broad object snapshot.","Support Hex-cleansing and chest-oriented builds."],"counters":["Only triggers when a generator is completed.","Object information may be redundant once you know the map.","Provides no Killer information."],"pros":["Large 64-metre Tier III range.","Twenty-second information window.","Shows multiple useful object categories."],"cons":["Trigger tied to generator completions.","No direct speed or survival effect.","Experienced map knowledge reduces value."],"analysis":["Detective's Hunch takes this position because sixty-four metres is a huge information radius, and twenty seconds is long enough to actually route toward the object you care about. One generator completion can reveal the next objective, several Totems, and available chests at once.","The perk is especially useful in Totem-focused builds. Counterforce, Inner Strength, and Overzealous all become easier to use when the player knows where remaining Totems actually are.","The information becomes less valuable as map knowledge improves. Experienced players already know common generator and Totem spawns, and the perk does not reveal the Killer or directly speed any interaction.","That keeps Detective's Hunch in lower B. It is excellent learning and build support, but not enough raw impact for a general meta slot."],"verdict":"A wide object-information snapshot that makes Totem and objective builds much smoother. Detective's Hunch is useful, but map knowledge slowly replaces part of its job.","publicationStatus":"published","tags":[],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"David Tapp"},"synergyPerkIds":["counterforce","inner-strength","overzealous","clairvoyance"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Counterforce","Inner Strength","Overzealous","Clairvoyance"],"antiSynergies":[],"name":"Detective's Hunch","alternateName":null,"source":"David Tapp","status":"Live 10.2.0","currentEffect":"Whenever a Generator is completed, the Auras of Chests, Generators, and Totems within 32/48/64 metres are revealed to you for 20 seconds. Maps no longer track the revealed objects.","activation":["A Generator is completed.","Ends/deactivates when: Aura reveal ends after 20 seconds."],"patchNote":"Latest live balance change (9.1.0): Set the Aura reveal to 20 seconds and removed map tracking of revealed objects.","plainEnglishSummary":"A completed Generator reveals nearby Chests, Generators, and Totems for a short time.","cooldown":null,"duration":["Aura reveal: 20 seconds."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["Maps no longer track objects revealed by this perk."],"sourceCharacter":"David Tapp","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"counterforce","rank":144,"tier":"C","roles":["Totem","Information"],"summary":"Cleanse Totems at 125% base speed, gain another stacking 25% cleanse-speed bonus per Totem, and reveal the farthest Totem after each cleanse.","metaStatus":"Situational","skillLevel":"Low","soloQ":3,"swf":2,"unlockPriority":"Medium","glossaryKeys":["pressure"],"useCases":["Rapidly clear a multi-Hex setup.","Chain Totem locations across the map using the farthest-Totem Aura reveal.","Support Overzealous or anti-Hex strategies with much faster cleansing."],"counters":["Provides little value when Totems are strategically irrelevant.","Travel time between far-apart Totems can dominate the saved cleanse time.","Cleansing every Dull Totem can interfere with Boon builds."],"pros":["Very fast cleansing after stacks build.","Self-guiding next-Totem information.","Excellent against heavy Hex builds."],"cons":["Extremely Totem-specific.","Can waste objective time if used without a reason to cleanse.","No benefit to blessing speed."],"analysis":["Counterforce ranks this position because it is superb at exactly one job: deleting Totems. The permanent 125% cleansing baseline already improves the interaction, and every completed cleanse adds another twenty-five-percent stack.","The farthest-Totem Aura reveal lets the perk chain its own objective. Instead of wandering after each cleanse, the player receives a clear next destination, making a deliberate Totem sweep much more practical.","The problem is whether a Totem sweep was worth doing in the first place. Against a dangerous Hex build, absolutely. Against five harmless Dull Totems, spending the match cleansing them can be worse than ignoring the perk entirely.","Counterforce therefore deserves a lower-B specialist ranking. It is an excellent answer to the right Killer build and unnecessary labor against the wrong one."],"verdict":"A premier anti-Totem specialist. Counterforce is fantastic when Hexes matter and actively harmful if it convinces you every Dull Totem must die.","publicationStatus":"published","tags":["Cleansing"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Jill Valentine"},"synergyPerkIds":["overzealous","inner-strength","detective-s-hunch","small-game"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Overzealous","Inner Strength","Detective's Hunch","Small Game"],"antiSynergies":[],"name":"Counterforce","alternateName":null,"source":"Jill Valentine","status":"Live 10.2.0","currentEffect":"Your Totem cleansing speed is set to 125%. Each Totem you cleanse adds a stackable 25% cleansing-speed bonus. After each cleanse, the Aura of the Totem farthest from your current location is revealed to you for 10/12/14 seconds.","activation":["Cleansing speed bonus is always active.","Cleanse a Totem to gain another stack and reveal the farthest Totem.","Ends/deactivates when: Farthest Totem Aura reveal ends after 10/12/14 seconds."],"patchNote":"Latest live balance change (9.0.0): Increased the bonus Totem cleansing speed to 25% and the farthest-Totem Aura reveal to 10/12/14 seconds.","plainEnglishSummary":"You cleanse Totems faster, gain additional cleansing speed per Totem cleansed, and see the farthest Totem after each cleanse.","cooldown":null,"duration":["Farthest Totem Aura reveal: 10/12/14 seconds by tier."],"tokenOrStackBehavior":"Permanent base cleansing speed is 125%; each cleansed Totem adds +25% stackable speed.","oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":[],"sourceCharacter":"Jill Valentine","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"}]);
